-- ============================================================
--  Experiencias de clase: Autocuidado de la tiroides
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  8 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Autocuidado de la tiroides$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Autocuidado de la tiroides$t$;
    RETURN;
  END IF;

  -- 01. Bienvenida: cómo usar este curso
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Bienvenida: cómo usar este curso$t$
     AND m.title = $u$Empieza aquí$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Bienvenida: cómo usar este curso$t$, $u$Empieza aquí$u$;
  ELSE
    v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Para qué te sirve: Bienvenida: cómo usar este curso","texto":"Imagina que tienes exámenes nuevos y no entiendes qué significan. Esta clase te ayuda a entender qué puedes hacer y qué preguntar, sin reemplazar a tu equipo de salud."},"objetivos":["Entender bienvenida: cómo usar este curso con palabras sencillas.","Reconocer qué información necesitas llevar a tu próxima consulta.","Saber qué puedes hacer por tu cuenta y qué debes consultar.","Preparar al menos tres preguntas para tu equipo de salud."],"conceptos":[{"icono":"Target","termino":"Idea principal","definicion":"Conoce la ruta de aprendizaje, los límites educativos del curso y cómo aprovechar cada clase para preparar mejores preguntas para tu equipo de salud."},{"icono":"Activity","termino":"Tiroides","definicion":"Una glándula del cuello que produce hormonas que ayudan a regular la energía, el peso, el ánimo y otros procesos del cuerpo."},{"icono":"Pill","termino":"Hormona tiroidea","definicion":"La sustancia que produce la tiroides y que el cuerpo necesita para funcionar; cuando falta, se reemplaza con medicamento."},{"icono":"ClipboardCheck","termino":"Examen de control","definicion":"Una prueba de sangre que ayuda a tu equipo de salud a saber cómo está funcionando el tratamiento."},{"icono":"Users","termino":"Adherencia","definicion":"Tomar el medicamento como fue indicado, a la misma hora y sin suspenderlo por cuenta propia."}],"secciones":[{"titulo":"Por qué este tema te importa","parrafos":["En tu día a día, bienvenida: cómo usar este curso aparece cuando tienes exámenes nuevos y no entiendes qué significan. No necesitas saberlo todo ni tomar decisiones médicas: necesitas entender qué está pasando y qué puedes hacer para cuidarte mejor.","Este curso es educativo. Te ayuda a entender tu tiroides, tus exámenes y tus medicamentos, y a preparar mejores preguntas. No reemplaza a tu médico ni a tu químico farmacéutico, y no sirve para cambiar tratamientos por tu cuenta."]},{"titulo":"Lo que necesitas saber","parrafos":["La idea principal de esta clase es: Conoce la ruta de aprendizaje, los límites educativos del curso y cómo aprovechar cada clase para preparar mejores preguntas para tu equipo de salud.","Para comprobar que lo entendiste, piensa en esta pregunta: «¿Para qué sirve este curso de autocuidado de la tiroides?» La explicación es: Este curso es educativo: te ayuda a entender tu tiroides, tus exámenes y tus medicamentos, y a preparar preguntas para tu médico y tu químico farmacéutico. No sirve para diagnosticar ni para cambiar tratamientos por tu cuenta.","Esta clase hace parte de «Empieza aquí». Lo que aprendas aquí te servirá para la siguiente clase y para tu próxima cita."]},{"titulo":"Cómo lo aplicas en tu vida","parrafos":["Puedes empezar hoy con pasos pequeños. Lo importante es que la información quede clara para ti y para tu equipo de salud.","Escribe en una lista los síntomas que has notado, desde cuándo y cómo son.","Anota los medicamentos, vitaminas y productos naturales que tomas, con la dosis y la hora.","Escribe tres preguntas concretas para tu médico.","Escribe dos preguntas para tu químico farmacéutico sobre tu medicamento.","Ordena las preguntas de la más importante a la menos importante.","Antes de la consulta, revisa tu lista y elige las tres preguntas que más te importan. Si algo te preocupa antes de la cita, no esperes: consulta."]},{"titulo":"Errores que conviene evitar","parrafos":["Evita esto: cambiar la dosis por cuenta propia. En su lugar: la dosis la ajusta el equipo de salud con exámenes de control.","Evita esto: suspender el medicamento porque te sientes bien. En su lugar: sentirte bien puede ser el efecto del tratamiento; suspenderlo puede devolver los síntomas.","Evita esto: comprar suplementos sin consultar. En su lugar: algunos productos cambian la absorción del medicamento; consúltalos primero.","Si algo no te queda claro, pregunta. Preguntar no es molestar: es parte de cuidarte y de tomar decisiones informadas con tu equipo de salud."]},{"titulo":"Cierre: tu próxima consulta","parrafos":["Al terminar esta clase deberías poder explicar bienvenida: cómo usar este curso con tus palabras, saber qué información llevar y tener al menos tres preguntas para tu equipo de salud. Si algo te preocupa, no esperes a la próxima cita."]}],"errores":[{"error":"Cambiar la dosis por cuenta propia","correccion":"La dosis la ajusta el equipo de salud con exámenes de control."},{"error":"Suspender el medicamento porque te sientes bien","correccion":"Sentirte bien puede ser el efecto del tratamiento; suspenderlo puede devolver los síntomas."},{"error":"Comprar suplementos sin consultar","correccion":"Algunos productos cambian la absorción del medicamento; consúltalos primero."}],"comprueba":[{"pregunta":"¿Qué aprendiste sobre «Bienvenida: cómo usar este curso»?","respuesta":"Conoce la ruta de aprendizaje, los límites educativos del curso y cómo aprovechar cada clase para preparar mejores preguntas para tu equipo de salud."},{"pregunta":"¿Qué harías antes de tu próxima consulta?","respuesta":"Anotar tus síntomas, revisar tus medicamentos y llevar tus preguntas. Eso ayuda a que la consulta sea más útil."},{"pregunta":"¿Qué no debes hacer por tu cuenta?","respuesta":"Cambiar la dosis, suspender el medicamento o comprar suplementos sin consultar. Esas decisiones las toma tu equipo de salud."}],"resumen":["Tu equipo de salud decide el tratamiento; tú puedes preparar la consulta.","Anotar síntomas y medicamentos ayuda a entender mejor lo que pasa.","Las promesas de cura rápida no reemplazan la consulta.","Si algo te preocupa, consulta antes de la próxima cita."],"referencias":[{"cita":"Bienvenida: cómo usar este curso","url":"https://youtu.be/RAUzM80hCO8"},{"cita":"MedlinePlus en español. Información de salud para pacientes.","url":"https://medlineplus.gov/spanish/"},{"cita":"Organización Mundial de la Salud. Información sobre la salud.","url":"https://www.who.int/es"},{"cita":"Ministerio de Salud y Protección Social. Información para la ciudadanía.","url":"https://www.minsalud.gov.co/"}],"imagenes":[{"ubicacion":"Apertura","descripcion":"Una persona preparando sus preguntas para una consulta sobre bienvenida: cómo usar este curso.","alt":"Autocuidado: bienvenida: cómo usar este curso"}],"keywords":["bienvenida","curso","empieza","tiroides","autocuidado","levotiroxina"],"mapa":{"centro":"Bienvenida: cómo usar este curso","ramas":[{"titulo":"Qué es","icono":"BookOpen","nodos":["Bienvenida: cómo usar este curso","Empieza aquí"]},{"titulo":"Por qué importa","icono":"Sparkles","nodos":["Tiroides","Hormona tiroidea","Examen de control"]},{"titulo":"Qué puedes hacer","icono":"CheckCircle2","nodos":["Escribe en una lista los síntomas que has notado, desde cuándo y cómo son.","Anota los medicamentos, vitaminas y productos naturales que tomas, con la dosis y la hora.","Escribe tres preguntas concretas para tu médico."]},{"titulo":"Cuándo consultar","icono":"AlertTriangle","nodos":["Si tienes un síntoma nuevo o intenso","Si no entiendes un resultado","Si piensas cambiar tu tratamiento"]}]},"proceso":{"titulo":"Cómo lo aplicas: Mis preguntas para la próxima consulta","intro":"No necesitas hacer todo de una vez. Empieza por lo que sí está en tus manos y lleva tus dudas a la consulta.","pasos":[{"titulo":"Paso 1","detalle":"Escribe en una lista los síntomas que has notado, desde cuándo y cómo son.","icono":"Search","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 2","detalle":"Anota los medicamentos, vitaminas y productos naturales que tomas, con la dosis y la hora.","icono":"ClipboardList","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 3","detalle":"Escribe tres preguntas concretas para tu médico.","icono":"FileCheck","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 4","detalle":"Escribe dos preguntas para tu químico farmacéutico sobre tu medicamento.","icono":"Users","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 5","detalle":"Ordena las preguntas de la más importante a la menos importante.","icono":"CheckCircle2","evidencia":"Tu lista o tus notas"}]},"caso":{"titulo":"Bienvenida: cómo usar este curso","contexto":"Imagina esta situación: Imagina que tienes una cita de control para tu tiroides en dos semanas (situación de práctica ficticia). El médico tendrá poco tiempo y quieres aprovecharlo. Desde hace dos meses te sientes más cansada, tomas levotiroxina en el desayuno junto con un suplemento de calcio y no recuerdas cuándo fue tu último examen. Tienes dudas sobre tus síntomas, tus exámenes y tu medicamento. La pregunta de esta clase es: ¿Para qué sirve este curso de autocuidado de la tiroides?","pregunta":"¿Qué harías en esta situación?","opciones":[{"texto":"Para diagnosticarte en casa sin necesidad de ir al médico ni de hacerte ningún examen.","correcta":false,"retro":"El curso no sirve para diagnosticar."},{"texto":"Para entender tu tiroides y preparar mejores preguntas para tu equipo de salud.","correcta":true,"retro":"Correcto. Es un curso educativo."},{"texto":"Para cambiar la dosis de tus medicamentos según cómo te sientas cada semana.","correcta":false,"retro":"Los cambios de dosis los decide tu médico."},{"texto":"Para reemplazar los controles médicos cuando ya te sientes bien con el tratamiento.","correcta":false,"retro":"Los controles siguen siendo necesarios."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. ¿Qué es la tiroides y para qué sirve?
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$¿Qué es la tiroides y para qué sirve?$t$
     AND m.title = $u$Comprende tu tiroides$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$¿Qué es la tiroides y para qué sirve?$t$, $u$Comprende tu tiroides$u$;
  ELSE
    v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Para qué te sirve: ¿Qué es la tiroides y para qué sirve?","texto":"Imagina que olvidaste una dosis y no sabes si debes tomar dos juntas. Esta clase te ayuda a entender qué puedes hacer y qué preguntar, sin reemplazar a tu equipo de salud."},"objetivos":["Entender ¿Qué es la tiroides y para qué sirve? con palabras sencillas.","Reconocer qué información necesitas llevar a tu próxima consulta.","Saber qué puedes hacer por tu cuenta y qué debes consultar.","Preparar al menos tres preguntas para tu equipo de salud."],"conceptos":[{"icono":"Target","termino":"Idea principal","definicion":"Revisa las funciones principales de la glándula tiroides y cómo sus hormonas se relacionan con diferentes sistemas del cuerpo."},{"icono":"Activity","termino":"Tiroides","definicion":"Una glándula del cuello que produce hormonas que ayudan a regular la energía, el peso, el ánimo y otros procesos del cuerpo."},{"icono":"Pill","termino":"Hormona tiroidea","definicion":"La sustancia que produce la tiroides y que el cuerpo necesita para funcionar; cuando falta, se reemplaza con medicamento."},{"icono":"ClipboardCheck","termino":"Examen de control","definicion":"Una prueba de sangre que ayuda a tu equipo de salud a saber cómo está funcionando el tratamiento."},{"icono":"Users","termino":"Adherencia","definicion":"Tomar el medicamento como fue indicado, a la misma hora y sin suspenderlo por cuenta propia."}],"secciones":[{"titulo":"Por qué este tema te importa","parrafos":["En tu día a día, ¿Qué es la tiroides y para qué sirve? aparece cuando olvidaste una dosis y no sabes si debes tomar dos juntas. No necesitas saberlo todo ni tomar decisiones médicas: necesitas entender qué está pasando y qué puedes hacer para cuidarte mejor.","Este curso es educativo. Te ayuda a entender tu tiroides, tus exámenes y tus medicamentos, y a preparar mejores preguntas. No reemplaza a tu médico ni a tu químico farmacéutico, y no sirve para cambiar tratamientos por tu cuenta."]},{"titulo":"Lo que necesitas saber","parrafos":["La idea principal de esta clase es: Revisa las funciones principales de la glándula tiroides y cómo sus hormonas se relacionan con diferentes sistemas del cuerpo.","Para comprobar que lo entendiste, piensa en esta pregunta: «¿Qué hacen las hormonas de la tiroides en el cuerpo?» La explicación es: La tiroides produce hormonas (T4 y T3) que regulan el metabolismo: cuánta energía usa el cuerpo, el ritmo del corazón, la temperatura, el intestino y muchas otras funciones. Por eso, cuando produce poco o mucho, aparecen síntomas en distintas partes del cuerpo.","Esta clase hace parte de «Comprende tu tiroides». Lo que aprendas aquí te servirá para la siguiente clase y para tu próxima cita."]},{"titulo":"Cómo lo aplicas en tu vida","parrafos":["Puedes empezar hoy con pasos pequeños. Lo importante es que la información quede clara para ti y para tu equipo de salud.","Haz una tabla con la fecha, el examen, el resultado, el valor de referencia del laboratorio y la dosis que tomabas.","Ubica en la tabla el cambio de dosis.","Describe con tus palabras cómo cambió la TSH después del cambio de dosis, sin sacar conclusiones médicas.","Escribe tres preguntas para tu médico sobre tus resultados.","Escribe cuándo crees que te toca el próximo control y confírmalo con tu médico.","Antes de la consulta, revisa tu lista y elige las tres preguntas que más te importan. Si algo te preocupa antes de la cita, no esperes: consulta."]},{"titulo":"Errores que conviene evitar","parrafos":["Evita esto: cambiar la dosis por cuenta propia. En su lugar: la dosis la ajusta el equipo de salud con exámenes de control.","Evita esto: suspender el medicamento porque te sientes bien. En su lugar: sentirte bien puede ser el efecto del tratamiento; suspenderlo puede devolver los síntomas.","Evita esto: comprar suplementos sin consultar. En su lugar: algunos productos cambian la absorción del medicamento; consúltalos primero.","Si algo no te queda claro, pregunta. Preguntar no es molestar: es parte de cuidarte y de tomar decisiones informadas con tu equipo de salud."]},{"titulo":"Cierre: tu próxima consulta","parrafos":["Al terminar esta clase deberías poder explicar ¿Qué es la tiroides y para qué sirve? con tus palabras, saber qué información llevar y tener al menos tres preguntas para tu equipo de salud. Si algo te preocupa, no esperes a la próxima cita."]}],"errores":[{"error":"Cambiar la dosis por cuenta propia","correccion":"La dosis la ajusta el equipo de salud con exámenes de control."},{"error":"Suspender el medicamento porque te sientes bien","correccion":"Sentirte bien puede ser el efecto del tratamiento; suspenderlo puede devolver los síntomas."},{"error":"Comprar suplementos sin consultar","correccion":"Algunos productos cambian la absorción del medicamento; consúltalos primero."}],"comprueba":[{"pregunta":"¿Qué aprendiste sobre «¿Qué es la tiroides y para qué sirve?»?","respuesta":"Revisa las funciones principales de la glándula tiroides y cómo sus hormonas se relacionan con diferentes sistemas del cuerpo."},{"pregunta":"¿Qué harías antes de tu próxima consulta?","respuesta":"Anotar tus síntomas, revisar tus medicamentos y llevar tus preguntas. Eso ayuda a que la consulta sea más útil."},{"pregunta":"¿Qué no debes hacer por tu cuenta?","respuesta":"Cambiar la dosis, suspender el medicamento o comprar suplementos sin consultar. Esas decisiones las toma tu equipo de salud."}],"resumen":["Tu equipo de salud decide el tratamiento; tú puedes preparar la consulta.","Anotar síntomas y medicamentos ayuda a entender mejor lo que pasa.","Las promesas de cura rápida no reemplazan la consulta.","Si algo te preocupa, consulta antes de la próxima cita."],"referencias":[{"cita":"¿Qué es la tiroides y para qué sirve?","url":"https://youtu.be/wXWsqg5C9Bo"},{"cita":"MedlinePlus en español. Información de salud para pacientes.","url":"https://medlineplus.gov/spanish/"},{"cita":"Organización Mundial de la Salud. Información sobre la salud.","url":"https://www.who.int/es"},{"cita":"Ministerio de Salud y Protección Social. Información para la ciudadanía.","url":"https://www.minsalud.gov.co/"}],"imagenes":[{"ubicacion":"Apertura","descripcion":"Una persona preparando sus preguntas para una consulta sobre ¿Qué es la tiroides y para qué sirve?.","alt":"Autocuidado: ¿Qué es la tiroides y para qué sirve?"}],"keywords":["tiroides","sirve","comprende","autocuidado","levotiroxina"],"mapa":{"centro":"¿Qué es la tiroides y para qué sirve?","ramas":[{"titulo":"Qué es","icono":"BookOpen","nodos":["¿Qué es la tiroides y para qué sirve?","Comprende tu tiroides"]},{"titulo":"Por qué importa","icono":"Sparkles","nodos":["Tiroides","Hormona tiroidea","Examen de control"]},{"titulo":"Qué puedes hacer","icono":"CheckCircle2","nodos":["Haz una tabla con la fecha, el examen, el resultado, el valor de referencia del laboratorio y la dosis que tomabas.","Ubica en la tabla el cambio de dosis.","Describe con tus palabras cómo cambió la TSH después del cambio de dosis, sin sacar conclusiones médicas."]},{"titulo":"Cuándo consultar","icono":"AlertTriangle","nodos":["Si tienes un síntoma nuevo o intenso","Si no entiendes un resultado","Si piensas cambiar tu tratamiento"]}]},"proceso":{"titulo":"Cómo lo aplicas: Mi registro de exámenes de tiroides","intro":"No necesitas hacer todo de una vez. Empieza por lo que sí está en tus manos y lleva tus dudas a la consulta.","pasos":[{"titulo":"Paso 1","detalle":"Haz una tabla con la fecha, el examen, el resultado, el valor de referencia del laboratorio y la dosis que tomabas.","icono":"Search","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 2","detalle":"Ubica en la tabla el cambio de dosis.","icono":"ClipboardList","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 3","detalle":"Describe con tus palabras cómo cambió la TSH después del cambio de dosis, sin sacar conclusiones médicas.","icono":"FileCheck","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 4","detalle":"Escribe tres preguntas para tu médico sobre tus resultados.","icono":"Users","evidencia":"Tu lista o tus notas"},{"titulo":"Paso 5","detalle":"Escribe cuándo crees que te toca el próximo control y confírmalo con tu médico.","icono":"CheckCircle2","evidencia":"Tu lista o tus notas"}]},"caso":{"titulo":"¿Qué es la tiroides y para qué sirve?","contexto":"Imagina esta situación: Imagina que tienes tres resultados de exámenes de tiroides de los últimos dos años en papeles distintos (situación de práctica con datos simulados): TSH de 6,8 hace dos años, de 3,1 hace un año y de 2,4 este año; T4 libre normal en los tres. Te cambiaron la dosis de levotiroxina hace un año. La pregunta de esta clase es: ¿Qué hacen las hormonas de la tiroides en el cuerpo?","pregunta":"¿Qué harías en esta situación?","opciones":[{"texto":"Solo controlan el crecimiento del cabello y de las uñas en los adultos.","correcta":false,"retro":"Sus funciones son mucho más amplias."},{"texto":"Solo regulan el azúcar de la sangre después de cada comida.","correcta":false,"retro":"Esa es una función de la insulina."},{"texto":"Regulan el metabolismo: la energía, el ritmo del corazón, la temperatura y otras funciones.","correcta":true,"retro":"Correcto. Por eso sus alteraciones dan síntomas tan variados."},{"texto":"Solo producen las defensas del cuerpo contra las infecciones.","correcta":false,"retro":"Esa es función del sistema inmune."}]}}$j$::jsonb;
