-- ============================================================
--  Experiencias de clase: Central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  9 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad$t$;
    RETURN;
  END IF;

  -- 01. El riesgo que se está conteniendo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$El riesgo que se está conteniendo$t$
     AND m.title = $u$Por qué lo estéril es distinto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$El riesgo que se está conteniendo$t$, $u$Por qué lo estéril es distinto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El riesgo que se está conteniendo","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una preparación estéril debe administrarse hoy y la central está en cambio de turno. Lo que está en juego es el criterio de el riesgo que se está conteniendo. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar el riesgo que se está conteniendo con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar el riesgo que se está conteniendo con por qué lo estéril es distinto y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar el riesgo que se está conteniendo y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Una preparación estéril entra directamente al torrente sanguíneo, saltándose las barreras naturales del cuerpo. Un error de esterilidad no da margen: por eso la central de mezclas tiene requisitos mucho más duros que cualquier otra preparación. Esta clase establece ese marco de riesgo."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el riesgo que se está conteniendo aparece en medio de una decisión que no admite improvisación: una preparación estéril debe administrarse hoy y la central está en cambio de turno. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de por qué lo estéril es distinto. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Una preparación estéril entra directamente al torrente sanguíneo, saltándose las barreras naturales del cuerpo. Un error de esterilidad no da margen: por eso la central de mezclas tiene requisitos mucho más duros que cualquier otra preparación. Esta clase establece ese marco de riesgo.","Una pregunta que se usa para comprobar esta clase es: «¿Por qué una preparación estéril para uso intravenoso exige controles más estrictos que una preparación oral no estéril?» La respuesta correcta se apoya en lo siguiente: La vía parenteral elimina las barreras del organismo. Por eso un error de esterilidad o de contaminación por partículas o endotoxinas no tiene margen y la central trabaja con áreas, controles y personal calificados. La fuente citada es: Capítulo 797 de la USP, introducción y alcance; Resolución 1403 de 2007.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a por qué lo estéril es distinto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa de riesgo de las preparaciones estériles de la clínica, con tabla y priorización.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar el riesgo que se está conteniendo, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y haz una lista con los datos de cada una de las seis preparaciones. Evidencia que debe quedar: Registro del paso.","Para cada una, anota los tres factores de riesgo de la clase 3: número de manipulaciones, tipo de envase o componente de partida y tiempo hasta la administración. Evidencia que debe quedar: Registro del paso.","Decide si es de uso inmediato o si debe prepararse en la central, y en qué categoría del capítulo 797 quedaría con las instalaciones actuales. Evidencia que debe quedar: Registro del paso.","Asigna la fecha límite de uso máxima que permitiría esa categoría y compárala con lo que hoy hace la clínica. Evidencia que debe quedar: Registro del paso.","Identifica qué preparaciones no pueden hacerse con las instalaciones actuales y explica por qué (por ejemplo, el citostático sin presión negativa). Evidencia que debe quedar: Registro del paso.","Prioriza los tres riesgos más graves y propone una medida concreta para cada uno. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En la Clínica Los Almendros (ficticia), las enfermeras diluyen en la estación todos los antibióticos y analgésicos intravenosos. En el último trimestre hubo dos bacteriemias asociadas a catéter en el mismo servicio (datos simulados). La farmacia propone centralizar; la coordinación de enfermería responde que la central no alcanza a cubrir las dosis urgentes de la noche y que «siempre se ha hecho así». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: preparar en un área no controlada Corrección: la cabina no compensa un entorno contaminado; el área y el flujo son parte del control.","Error: confundir estabilidad con esterilidad Corrección: una preparación puede ser estable y estar contaminada; son controles distintos.","Error: improvisar ante una incompatibilidad Corrección: la duda se resuelve con la ficha técnica y el protocolo, no con la costumbre.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar el riesgo que se está conteniendo en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «El riesgo que se está conteniendo»?","respuesta":"Una preparación estéril entra directamente al torrente sanguíneo, saltándose las barreras naturales del cuerpo. Un error de esterilidad no da margen: por eso la central de mezclas tiene requisitos mucho más duros que cualquier otra preparación. Esta clase establece ese marco de riesgo."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa de riesgo de las preparaciones estériles de la clínica, con tabla y priorización.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["El riesgo que se está conteniendo se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con por qué lo estéril es distinto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"USP · Capítulo 797, preparaciones estériles. El capítulo que ordena toda la práctica estéril por niveles de riesgo. Lee el alcance y las definiciones.","url":"https://www.usp.org/compounding/general-chapter-797"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente el riesgo que se está conteniendo en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de el riesgo que se está conteniendo"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","riesgo","conteniendo","estéril","distinto"],"mapa":{"centro":"El riesgo que se está conteniendo","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Por qué lo estéril es distinto","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa de riesgo de las preparaciones de una clínica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y haz una lista con los datos de cada una de las seis preparaciones.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para cada una, anota los tres factores de riesgo de la clase 3: número de manipulaciones, tipo de envase o componente de partida y tiempo hasta la administración.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Decide si es de uso inmediato o si debe prepararse en la central, y en qué categoría del capítulo 797 quedaría con las instalaciones actuales.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Asigna la fecha límite de uso máxima que permitiría esa categoría y compárala con lo que hoy hace la clínica.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Identifica qué preparaciones no pueden hacerse con las instalaciones actuales y explica por qué (por ejemplo, el citostático sin presión negativa).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prioriza los tres riesgos más graves y propone una medida concreta para cada uno.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"El riesgo que se está conteniendo","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de por qué lo estéril es distinto: La Clínica Santa Clara (ficticia), de 180 camas, quiere ordenar sus preparaciones estériles antes de solicitar la certificación de su central de mezclas. Hoy prepara: (1) ceftriaxona reconstituida en urgencias para administrar en bolo de inmediato; (2) nutrición parenteral neonatal con aminoácidos, dextrosa, lípidos, electrolitos y oligoelementos; (3) ciclofosfamida para pacientes ambulatorios de oncología; (4) jeringas de morfina para analgesia controlada por el paciente, preparadas el lunes para toda la semana; (5) bevacizumab fraccionado en jeringas para uso intravítreo a partir de un vial de uso único; (6) bolsas de bupivacaína con fentanilo para analgesia epidural. La central tiene una antesala ISO 8, una sala de amortiguamiento ISO 7 con una cabina de flujo laminar horizontal y ninguna zona de presión negativa. La pregunta que decide esta clase es: ¿Por qué una preparación estéril para uso intravenoso exige controles más estrictos que una preparación oral no estéril?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Porque entra directo al torrente sanguíneo, sin las barreras del cuerpo que frenan microorganismos, endotoxinas y partículas.","correcta":true,"retro":"Correcto. Ese es el riesgo que la central contiene: no hay piel, mucosa ni ácido gástrico que frenen la contaminación."},{"texto":"Porque los medicamentos intravenosos tienen siempre concentraciones más altas que los orales y eso los vuelve inestables y difíciles de controlar.","correcta":false,"retro":"La concentración no define la exigencia. Un intravenoso diluido es tan crítico como uno concentrado si se contamina."},{"texto":"Porque las preparaciones intravenosas solo se usan en pacientes de cuidado intensivo, que son los únicos inmunosuprimidos.","correcta":false,"retro":"También se administran en hospitalización general y en casa. El riesgo viene de la vía, no del servicio."},{"texto":"Porque la norma colombiana exige registro sanitario para toda preparación intravenosa elaborada en una central.","correcta":false,"retro":"Las preparaciones de la central no llevan registro sanitario; la exigencia viene del riesgo de la vía parenteral."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Normativa aplicable
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Normativa aplicable$t$
     AND m.title = $u$Por qué lo estéril es distinto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Normativa aplicable$t$, $u$Por qué lo estéril es distinto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Normativa aplicable","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una etiqueta no permite reconstruir quién preparó la mezcla. Lo que está en juego es el criterio de normativa aplicable. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar normativa aplicable con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar normativa aplicable con por qué lo estéril es distinto y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar normativa aplicable y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La Resolución 1403 de 2007 regula las preparaciones estériles en Colombia, y el capítulo USP 797 es la referencia internacional que ordena el tema por niveles de riesgo. Se revisa qué exige cada una y cómo se complementan."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, normativa aplicable aparece en medio de una decisión que no admite improvisación: una etiqueta no permite reconstruir quién preparó la mezcla. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de por qué lo estéril es distinto. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La Resolución 1403 de 2007 regula las preparaciones estériles en Colombia, y el capítulo USP 797 es la referencia internacional que ordena el tema por niveles de riesgo. Se revisa qué exige cada una y cómo se complementan.","Una pregunta que se usa para comprobar esta clase es: «En una auditoría interna, el químico farmacéutico encuentra un procedimiento que cita solo el capítulo 797 de la USP y ninguna norma colombiana. ¿Qué análisis es correcto sobre la relación entre ambas referencias?» La respuesta correcta se apoya en lo siguiente: La obligación legal en Colombia viene de la Resolución 1403 de 2007 (y del Decreto 2200 de 2005 que desarrolla). El capítulo 797 de la USP es la referencia internacional que ordena la práctica y ayuda a sustentar decisiones técnicas. La fuente citada es: Resolución 1403 de 2007; capítulo 797 de la USP.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a por qué lo estéril es distinto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa de riesgo de las preparaciones estériles de la clínica, con tabla y priorización.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar normativa aplicable, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y haz una lista con los datos de cada una de las seis preparaciones. Evidencia que debe quedar: Registro del paso.","Para cada una, anota los tres factores de riesgo de la clase 3: número de manipulaciones, tipo de envase o componente de partida y tiempo hasta la administración. Evidencia que debe quedar: Registro del paso.","Decide si es de uso inmediato o si debe prepararse en la central, y en qué categoría del capítulo 797 quedaría con las instalaciones actuales. Evidencia que debe quedar: Registro del paso.","Asigna la fecha límite de uso máxima que permitiría esa categoría y compárala con lo que hoy hace la clínica. Evidencia que debe quedar: Registro del paso.","Identifica qué preparaciones no pueden hacerse con las instalaciones actuales y explica por qué (por ejemplo, el citostático sin presión negativa). Evidencia que debe quedar: Registro del paso.","Prioriza los tres riesgos más graves y propone una medida concreta para cada uno. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Error: confundir estabilidad con esterilidad Corrección: una preparación puede ser estable y estar contaminada; son controles distintos.","Error: almacenar una preparación de uso inmediato Corrección: el uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar normativa aplicable en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Normativa aplicable»?","respuesta":"La Resolución 1403 de 2007 regula las preparaciones estériles en Colombia, y el capítulo USP 797 es la referencia internacional que ordena el tema por niveles de riesgo. Se revisa qué exige cada una y cómo se complementan."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa de riesgo de las preparaciones estériles de la clínica, con tabla y priorización.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Normativa aplicable se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con por qué lo estéril es distinto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"Resolución 1403 de 2007 · Preparaciones estériles. La norma colombiana que regula la central de mezclas: condiciones, personal y procesos.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCION%201403%20DE%202007.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente normativa aplicable en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de normativa aplicable"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","normativa","aplicable","estéril","distinto"],"mapa":{"centro":"Normativa aplicable","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Por qué lo estéril es distinto","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa de riesgo de las preparaciones de una clínica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y haz una lista con los datos de cada una de las seis preparaciones.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para cada una, anota los tres factores de riesgo de la clase 3: número de manipulaciones, tipo de envase o componente de partida y tiempo hasta la administración.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Decide si es de uso inmediato o si debe prepararse en la central, y en qué categoría del capítulo 797 quedaría con las instalaciones actuales.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Asigna la fecha límite de uso máxima que permitiría esa categoría y compárala con lo que hoy hace la clínica.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Identifica qué preparaciones no pueden hacerse con las instalaciones actuales y explica por qué (por ejemplo, el citostático sin presión negativa).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prioriza los tres riesgos más graves y propone una medida concreta para cada uno.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Normativa aplicable","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de por qué lo estéril es distinto: La Clínica Santa Clara (ficticia), de 180 camas, quiere ordenar sus preparaciones estériles antes de solicitar la certificación de su central de mezclas. Hoy prepara: (1) ceftriaxona reconstituida en urgencias para administrar en bolo de inmediato; (2) nutrición parenteral neonatal con aminoácidos, dextrosa, lípidos, electrolitos y oligoelementos; (3) ciclofosfamida para pacientes ambulatorios de oncología; (4) jeringas de morfina para analgesia controlada por el paciente, preparadas el lunes para toda la semana; (5) bevacizumab fraccionado en jeringas para uso intravítreo a partir de un vial de uso único; (6) bolsas de bupivacaína con fentanilo para analgesia epidural. La central tiene una antesala ISO 8, una sala de amortiguamiento ISO 7 con una cabina de flujo laminar horizontal y ninguna zona de presión negativa. La pregunta que decide esta clase es: En una auditoría interna, el químico farmacéutico encuentra un procedimiento que cita solo el capítulo 797 de la USP y ninguna norma colombiana. ¿Qué análisis es correcto sobre la relación entre ambas referencias?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"La USP reemplaza a la norma colombiana porque es más reciente y más detallada, así que el procedimiento está completo y no necesita otra cita.","correcta":false,"retro":"La USP no es obligatoria en Colombia. Su actualización no deroga ni reemplaza la norma nacional."},{"texto":"Son incompatibles: si el procedimiento cita la USP, debe eliminarla y dejar solo la Resolución 1403 de 2007.","correcta":false,"retro":"No son excluyentes. La USP sirve de soporte técnico donde la norma colombiana es menos específica."},{"texto":"La norma colombiana solo aplica a preparaciones no estériles; para lo estéril la referencia obligatoria es la USP.","correcta":false,"retro":"La Resolución 1403 de 2007 sí regula las preparaciones estériles de la central de mezclas en Colombia."},{"texto":"Es obligatoria la Resolución 1403 de 2007; la USP es una referencia técnica que la complementa, y el procedimiento debe citar las dos.","correcta":true,"retro":"Correcto. Se cumple la norma nacional y se usa la USP para precisar lo técnico, sin presentarla como obligatoria."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Niveles de riesgo de una preparación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Niveles de riesgo de una preparación$t$
     AND m.title = $u$Por qué lo estéril es distinto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Niveles de riesgo de una preparación$t$, $u$Por qué lo estéril es distinto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Niveles de riesgo de una preparación","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una preparación se almacenó más tiempo del permitido. Lo que está en juego es el criterio de niveles de riesgo de una preparación. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar niveles de riesgo de una preparación con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar niveles de riesgo de una preparación con por qué lo estéril es distinto y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar niveles de riesgo de una preparación y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"No todas las mezclas tienen el mismo riesgo: influyen el número de manipulaciones, el tipo de envase de partida y el tiempo hasta la administración. Clasificar bien el riesgo determina el área, los controles y la fecha límite de uso."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, niveles de riesgo de una preparación aparece en medio de una decisión que no admite improvisación: una preparación se almacenó más tiempo del permitido. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de por qué lo estéril es distinto. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: No todas las mezclas tienen el mismo riesgo: influyen el número de manipulaciones, el tipo de envase de partida y el tiempo hasta la administración. Clasificar bien el riesgo determina el área, los controles y la fecha límite de uso.","Una pregunta que se usa para comprobar esta clase es: «Una clínica sin sala limpia prepara jeringas de antibiótico en una cabina de flujo laminar ISO 5 ubicada en un área segregada. Enfermería pide guardarlas 72 horas en nevera. Según la revisión vigente del capítulo 797 de la USP, ¿qué fecha límite de uso máxima corresponde?» La respuesta correcta se apoya en lo siguiente: La revisión de 2023 del capítulo 797 reemplazó los niveles de riesgo por categorías. La categoría 1 se prepara en un área segregada y admite como máximo 12 horas a temperatura ambiente o 24 horas refrigerada. La fuente citada es: Capítulo 797 de la USP (2023), categorías de preparación y fechas límite de uso.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a por qué lo estéril es distinto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Mapa de riesgo de las preparaciones estériles de la clínica, con tabla y priorización.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar niveles de riesgo de una preparación, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y haz una lista con los datos de cada una de las seis preparaciones. Evidencia que debe quedar: Registro del paso.","Para cada una, anota los tres factores de riesgo de la clase 3: número de manipulaciones, tipo de envase o componente de partida y tiempo hasta la administración. Evidencia que debe quedar: Registro del paso.","Decide si es de uso inmediato o si debe prepararse en la central, y en qué categoría del capítulo 797 quedaría con las instalaciones actuales. Evidencia que debe quedar: Registro del paso.","Asigna la fecha límite de uso máxima que permitiría esa categoría y compárala con lo que hoy hace la clínica. Evidencia que debe quedar: Registro del paso.","Identifica qué preparaciones no pueden hacerse con las instalaciones actuales y explica por qué (por ejemplo, el citostático sin presión negativa). Evidencia que debe quedar: Registro del paso.","Prioriza los tres riesgos más graves y propone una medida concreta para cada uno. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En la Clínica Los Almendros (ficticia), las enfermeras diluyen en la estación todos los antibióticos y analgésicos intravenosos. En el último trimestre hubo dos bacteriemias asociadas a catéter en el mismo servicio (datos simulados). La farmacia propone centralizar; la coordinación de enfermería responde que la central no alcanza a cubrir las dosis urgentes de la noche y que «siempre se ha hecho así». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir estabilidad con esterilidad Corrección: una preparación puede ser estable y estar contaminada; son controles distintos.","Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Error: almacenar una preparación de uso inmediato Corrección: el uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar niveles de riesgo de una preparación en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Niveles de riesgo de una preparación»?","respuesta":"No todas las mezclas tienen el mismo riesgo: influyen el número de manipulaciones, el tipo de envase de partida y el tiempo hasta la administración. Clasificar bien el riesgo determina el área, los controles y la fecha límite de uso."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Mapa de riesgo de las preparaciones estériles de la clínica, con tabla y priorización.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Niveles de riesgo de una preparación se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con por qué lo estéril es distinto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"USP · Capítulo 797, categorías de preparación. Cómo se clasifica el riesgo según manipulaciones, envase de partida y tiempo hasta la administración.","url":"https://www.usp.org/compounding/general-chapter-797"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente niveles de riesgo de una preparación en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de niveles de riesgo de una preparación"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","niveles","riesgo","preparación","estéril","distinto"],"mapa":{"centro":"Niveles de riesgo de una preparación","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Por qué lo estéril es distinto","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Mapa de riesgo de las preparaciones de una clínica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y haz una lista con los datos de cada una de las seis preparaciones.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para cada una, anota los tres factores de riesgo de la clase 3: número de manipulaciones, tipo de envase o componente de partida y tiempo hasta la administración.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Decide si es de uso inmediato o si debe prepararse en la central, y en qué categoría del capítulo 797 quedaría con las instalaciones actuales.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Asigna la fecha límite de uso máxima que permitiría esa categoría y compárala con lo que hoy hace la clínica.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Identifica qué preparaciones no pueden hacerse con las instalaciones actuales y explica por qué (por ejemplo, el citostático sin presión negativa).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prioriza los tres riesgos más graves y propone una medida concreta para cada uno.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Niveles de riesgo de una preparación","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de por qué lo estéril es distinto: La Clínica Santa Clara (ficticia), de 180 camas, quiere ordenar sus preparaciones estériles antes de solicitar la certificación de su central de mezclas. Hoy prepara: (1) ceftriaxona reconstituida en urgencias para administrar en bolo de inmediato; (2) nutrición parenteral neonatal con aminoácidos, dextrosa, lípidos, electrolitos y oligoelementos; (3) ciclofosfamida para pacientes ambulatorios de oncología; (4) jeringas de morfina para analgesia controlada por el paciente, preparadas el lunes para toda la semana; (5) bevacizumab fraccionado en jeringas para uso intravítreo a partir de un vial de uso único; (6) bolsas de bupivacaína con fentanilo para analgesia epidural. La central tiene una antesala ISO 8, una sala de amortiguamiento ISO 7 con una cabina de flujo laminar horizontal y ninguna zona de presión negativa. La pregunta que decide esta clase es: Una clínica sin sala limpia prepara jeringas de antibiótico en una cabina de flujo laminar ISO 5 ubicada en un área segregada. Enfermería pide guardarlas 72 horas en nevera. Según la revisión vigente del capítulo 797 de la USP, ¿qué fecha límite de uso máxima corresponde?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"72 horas en refrigeración, porque la nevera conserva la esterilidad mientras el empaque esté cerrado.","correcta":false,"retro":"La nevera retarda el crecimiento, pero no compensa la falta de sala limpia. El área segregada limita la preparación a la categoría 1."},{"texto":"10 días en refrigeración, porque la jeringa se preparó a partir de componentes estériles.","correcta":false,"retro":"Esos 10 días aplican a la categoría 2, que exige preparar dentro de una sala limpia. Aquí no la hay."},{"texto":"24 horas en refrigeración o 12 horas a temperatura ambiente, porque es una preparación de categoría 1.","correcta":true,"retro":"Correcto. En un área segregada solo se elaboran preparaciones de categoría 1, con esos límites."},{"texto":"4 horas desde el inicio de la preparación, porque toda preparación hecha fuera de la central es de uso inmediato.","correcta":false,"retro":"El uso inmediato es otra figura, para administrar sin almacenar. Aquí se prepara en una cabina y se quiere almacenar."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 04. Clasificación de áreas limpias
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Clasificación de áreas limpias$t$
     AND m.title = $u$Áreas limpias y técnica aséptica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Clasificación de áreas limpias$t$, $u$Áreas limpias y técnica aséptica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Clasificación de áreas limpias","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una preparación se almacenó más tiempo del permitido. Lo que está en juego es el criterio de clasificación de áreas limpias. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar clasificación de áreas limpias con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar clasificación de áreas limpias con áreas limpias y técnica aséptica y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar clasificación de áreas limpias y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Se revisa la norma ISO 14644 y la clasificación por partículas, qué significa trabajar en ISO 5 dentro de un ambiente ISO 7, y el papel de las presiones diferenciales y las esclusas. El objetivo es entender por qué el aire se diseña como se diseña."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, clasificación de áreas limpias aparece en medio de una decisión que no admite improvisación: una preparación se almacenó más tiempo del permitido. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de áreas limpias y técnica aséptica. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Se revisa la norma ISO 14644 y la clasificación por partículas, qué significa trabajar en ISO 5 dentro de un ambiente ISO 7, y el papel de las presiones diferenciales y las esclusas. El objetivo es entender por qué el aire se diseña como se diseña.","Una pregunta que se usa para comprobar esta clase es: «¿Por qué en una central de mezclas se trabaja en un ambiente ISO 5 dentro de una sala ISO 7, y no al revés?» La respuesta correcta se apoya en lo siguiente: El diseño del aire es por capas: la cabina entrega aire HEPA unidireccional ISO 5 sobre el sitio crítico; la sala de amortiguamiento ISO 7 y la antesala reducen la carga y, con presiones diferenciales, evitan que entre aire sucio. La fuente citada es: ISO 14644-1; capítulo 797 de la USP (2023), instalaciones.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a áreas limpias y técnica aséptica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe técnico de diagnóstico de áreas y técnica, con tabla de resultados y plan de corrección.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar clasificación de áreas limpias, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el informe y arma una tabla con cada resultado, su criterio y si cumple. Evidencia que debe quedar: Registro del paso.","Analiza el diferencial de presión y el número de renovaciones de aire frente a lo que exige la referencia técnica. Evidencia que debe quedar: Registro del paso.","Lista las fallas de técnica observadas y explica qué riesgo crea cada una. Evidencia que debe quedar: Registro del paso.","Decide qué preparaciones pueden continuar mientras se corrige y cuáles deben suspenderse. Evidencia que debe quedar: Registro del paso.","Explica qué le falta a la central para preparar quimioterapia (área, cabina, presión y personal). Evidencia que debe quedar: Registro del paso.","Propón un plan de corrección con responsables y fecha para cada hallazgo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: preparar en un área no controlada Corrección: la cabina no compensa un entorno contaminado; el área y el flujo son parte del control.","Error: almacenar una preparación de uso inmediato Corrección: el uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles.","Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar clasificación de áreas limpias en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Clasificación de áreas limpias»?","respuesta":"Se revisa la norma ISO 14644 y la clasificación por partículas, qué significa trabajar en ISO 5 dentro de un ambiente ISO 7, y el papel de las presiones diferenciales y las esclusas. El objetivo es entender por qué el aire se diseña como se diseña."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe técnico de diagnóstico de áreas y técnica, con tabla de resultados y plan de corrección.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Clasificación de áreas limpias se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con áreas limpias y técnica aséptica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"Métodos para la validación de áreas en la industria farmacéutica · Bioanálisis Farmacéuticos · 26 min","url":"https://www.youtube.com/watch?v=IREMoaJJV08"},{"cita":"UE · Anexo 1, fabricación de medicamentos estériles. La revisión de 2022 del Anexo 1: clasificación de áreas, estrategia de control de contaminación y monitoreo.","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente clasificación de áreas limpias en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de clasificación de áreas limpias"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","clasificación","áreas","limpias","técnica","aséptica"],"mapa":{"centro":"Clasificación de áreas limpias","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Áreas limpias y técnica aséptica","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Diagnóstico de áreas y técnica de una central","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el informe y arma una tabla con cada resultado, su criterio y si cumple.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza el diferencial de presión y el número de renovaciones de aire frente a lo que exige la referencia técnica.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Lista las fallas de técnica observadas y explica qué riesgo crea cada una.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide qué preparaciones pueden continuar mientras se corrige y cuáles deben suspenderse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Explica qué le falta a la central para preparar quimioterapia (área, cabina, presión y personal).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón un plan de corrección con responsables y fecha para cada hallazgo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación de áreas limpias","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de áreas limpias y técnica aséptica: La central de mezclas del Hospital Río Claro (ficticio) recibió su informe de recertificación semestral y una observación de la técnica de dos auxiliares. Datos simulados: antesala (diseño ISO 8) con 1.900.000 partículas de 0,5 µm por metro cúbico; sala de amortiguamiento (diseño ISO 7) con 395.000; cabina de flujo laminar horizontal ISO 5 con 2.800; diferencial de presión entre sala y antesala de 0,008 pulgadas de columna de agua; 32 renovaciones de aire por hora en la sala. Observación: una auxiliar trabaja con los antebrazos dentro de la cabina pero bloquea con la bolsa el aire que llega al punto de inyección; el otro rocía alcohol sobre los viales sin dejar secar y entra a la sala con reloj. La gerencia quiere empezar a preparar quimioterapia el próximo mes en la misma sala. La pregunta que decide esta clase es: ¿Por qué en una central de mezclas se trabaja en un ambiente ISO 5 dentro de una sala ISO 7, y no al revés?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Porque la sala ISO 7 filtra el aire de la cabina y así la cabina no necesita un filtro HEPA propio sobre la zona de trabajo.","correcta":false,"retro":"La cabina sí tiene filtro HEPA propio: es la que entrega el aire de primera pasada sobre el sitio crítico."},{"texto":"Porque el sitio crítico necesita el aire más limpio y la sala que lo rodea reduce la carga de partículas que llega a la cabina.","correcta":true,"retro":"Correcto. El diseño protege el sitio crítico con capas: la cabina ISO 5, donde se abre el vial y se manipula, y una sala ISO 7 que la rodea."},{"texto":"Porque la norma prohíbe, por razones de costo y de consumo de energía, que una sala completa se diseñe como ISO 5.","correcta":false,"retro":"No es una prohibición por costo. La clasificación responde a dónde está el riesgo de contaminación."},{"texto":"Porque así el aire de la cabina sale hacia la sala y la mantiene en ISO 7 sin necesidad de presiones diferenciales.","correcta":false,"retro":"Las presiones diferenciales siguen siendo necesarias para que el aire fluya de lo más limpio a lo menos limpio."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 05. Cabinas de seguridad y flujo laminar
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Cabinas de seguridad y flujo laminar$t$
     AND m.title = $u$Áreas limpias y técnica aséptica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Cabinas de seguridad y flujo laminar$t$, $u$Áreas limpias y técnica aséptica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cabinas de seguridad y flujo laminar","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una preparación se almacenó más tiempo del permitido. Lo que está en juego es el criterio de cabinas de seguridad y flujo laminar. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar cabinas de seguridad y flujo laminar con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar cabinas de seguridad y flujo laminar con áreas limpias y técnica aséptica y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar cabinas de seguridad y flujo laminar y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Diferencia entre una cabina de flujo laminar y una de seguridad biológica, cuándo se usa cada una y por qué una mezcla oncológica no puede prepararse en cualquiera. También cómo se trabaja dentro sin romper el flujo de aire."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, cabinas de seguridad y flujo laminar aparece en medio de una decisión que no admite improvisación: una preparación se almacenó más tiempo del permitido. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de áreas limpias y técnica aséptica. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Diferencia entre una cabina de flujo laminar y una de seguridad biológica, cuándo se usa cada una y por qué una mezcla oncológica no puede prepararse en cualquiera. También cómo se trabaja dentro sin romper el flujo de aire.","Una pregunta que se usa para comprobar esta clase es: «Un hospital tiene una cabina de flujo laminar horizontal y una cabina de seguridad biológica clase II dentro de una sala de presión negativa. Hoy debe preparar una nutrición parenteral, una jeringa de vancomicina y una infusión de metotrexato. ¿Qué distribución es correcta?» La respuesta correcta se apoya en lo siguiente: La cabina horizontal protege el producto y dirige el aire hacia el operador: sirve para lo no peligroso. La cabina de seguridad biológica clase II, en una sala de presión negativa, protege también a quien prepara y es la indicada para los citostáticos. La fuente citada es: Capítulo 800 de la USP, controles de ingeniería; capítulo 797 de la USP.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a áreas limpias y técnica aséptica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe técnico de diagnóstico de áreas y técnica, con tabla de resultados y plan de corrección.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar cabinas de seguridad y flujo laminar, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el informe y arma una tabla con cada resultado, su criterio y si cumple. Evidencia que debe quedar: Registro del paso.","Analiza el diferencial de presión y el número de renovaciones de aire frente a lo que exige la referencia técnica. Evidencia que debe quedar: Registro del paso.","Lista las fallas de técnica observadas y explica qué riesgo crea cada una. Evidencia que debe quedar: Registro del paso.","Decide qué preparaciones pueden continuar mientras se corrige y cuáles deben suspenderse. Evidencia que debe quedar: Registro del paso.","Explica qué le falta a la central para preparar quimioterapia (área, cabina, presión y personal). Evidencia que debe quedar: Registro del paso.","Propón un plan de corrección con responsables y fecha para cada hallazgo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Error: preparar en un área no controlada Corrección: la cabina no compensa un entorno contaminado; el área y el flujo son parte del control.","Error: confundir estabilidad con esterilidad Corrección: una preparación puede ser estable y estar contaminada; son controles distintos.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar cabinas de seguridad y flujo laminar en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Cabinas de seguridad y flujo laminar»?","respuesta":"Diferencia entre una cabina de flujo laminar y una de seguridad biológica, cuándo se usa cada una y por qué una mezcla oncológica no puede prepararse en cualquiera. También cómo se trabaja dentro sin romper el flujo de aire."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe técnico de diagnóstico de áreas y técnica, con tabla de resultados y plan de corrección.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Cabinas de seguridad y flujo laminar se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con áreas limpias y técnica aséptica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"FDA · Sterile Drug Products Produced by Aseptic Processing. Cómo se diseña y se opera el aire que protege la preparación. Capítulos de instalaciones y flujo unidireccional.","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/sterile-drug-products-produced-aseptic-processing-current-good-manufacturing-practice"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente cabinas de seguridad y flujo laminar en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de cabinas de seguridad y flujo laminar"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","cabinas","seguridad","flujo","laminar","áreas","limpias"],"mapa":{"centro":"Cabinas de seguridad y flujo laminar","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Áreas limpias y técnica aséptica","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Diagnóstico de áreas y técnica de una central","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el informe y arma una tabla con cada resultado, su criterio y si cumple.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza el diferencial de presión y el número de renovaciones de aire frente a lo que exige la referencia técnica.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Lista las fallas de técnica observadas y explica qué riesgo crea cada una.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide qué preparaciones pueden continuar mientras se corrige y cuáles deben suspenderse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Explica qué le falta a la central para preparar quimioterapia (área, cabina, presión y personal).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón un plan de corrección con responsables y fecha para cada hallazgo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Cabinas de seguridad y flujo laminar","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de áreas limpias y técnica aséptica: La central de mezclas del Hospital Río Claro (ficticio) recibió su informe de recertificación semestral y una observación de la técnica de dos auxiliares. Datos simulados: antesala (diseño ISO 8) con 1.900.000 partículas de 0,5 µm por metro cúbico; sala de amortiguamiento (diseño ISO 7) con 395.000; cabina de flujo laminar horizontal ISO 5 con 2.800; diferencial de presión entre sala y antesala de 0,008 pulgadas de columna de agua; 32 renovaciones de aire por hora en la sala. Observación: una auxiliar trabaja con los antebrazos dentro de la cabina pero bloquea con la bolsa el aire que llega al punto de inyección; el otro rocía alcohol sobre los viales sin dejar secar y entra a la sala con reloj. La gerencia quiere empezar a preparar quimioterapia el próximo mes en la misma sala. La pregunta que decide esta clase es: Un hospital tiene una cabina de flujo laminar horizontal y una cabina de seguridad biológica clase II dentro de una sala de presión negativa. Hoy debe preparar una nutrición parenteral, una jeringa de vancomicina y una infusión de metotrexato. ¿Qué distribución es correcta?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"El metotrexato en la cabina de seguridad biológica; la nutrición y la vancomicina en la cabina de flujo laminar.","correcta":true,"retro":"Correcto. El peligroso va donde el aire protege a quien prepara; lo no peligroso, donde el flujo protege la preparación."},{"texto":"Las tres en la cabina de flujo laminar horizontal, porque es la que entrega el aire más limpio y unidireccional sobre la preparación.","correcta":false,"retro":"El flujo horizontal sopla hacia el operador: con un citostático lo expone directamente."},{"texto":"El metotrexato en la cabina horizontal con doble guante, y las otras dos en la cabina de seguridad biológica.","correcta":false,"retro":"El doble guante no compensa un flujo que sale hacia la cara del operador."},{"texto":"Las tres en la cabina de seguridad biológica, porque es la única que protege al producto, al operador y al ambiente.","correcta":false,"retro":"Usar la cabina de peligrosos para todo expone las preparaciones no peligrosas a contaminación cruzada con el citostático."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 06. Técnica aséptica y su validación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Técnica aséptica y su validación$t$
     AND m.title = $u$Áreas limpias y técnica aséptica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Técnica aséptica y su validación$t$, $u$Áreas limpias y técnica aséptica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Técnica aséptica y su validación","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una prescripción llega incompleta y el área de preparación tiene presión de tiempo. Lo que está en juego es el criterio de técnica aséptica y su validación. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar técnica aséptica y su validación con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar técnica aséptica y su validación con áreas limpias y técnica aséptica y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar técnica aséptica y su validación y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La técnica aséptica se aprende y se demuestra: el llenado con medio de cultivo, conocido como media fill, es la prueba de que quien prepara puede hacerlo sin contaminar. Se revisa cómo se hace, cada cuánto y qué pasa si falla."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, técnica aséptica y su validación aparece en medio de una decisión que no admite improvisación: una prescripción llega incompleta y el área de preparación tiene presión de tiempo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de áreas limpias y técnica aséptica. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La técnica aséptica se aprende y se demuestra: el llenado con medio de cultivo, conocido como media fill, es la prueba de que quien prepara puede hacerlo sin contaminar. Se revisa cómo se hace, cada cuánto y qué pasa si falla.","Una pregunta que se usa para comprobar esta clase es: «El llenado con medio de cultivo (media fill) de un técnico sale turbio durante la incubación. El jefe de la central decide repetir la prueba el próximo semestre y dejar al técnico trabajando mientras tanto. ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: El media fill demuestra que una persona puede manipular sin contaminar. Si falla, la persona deja de elaborar hasta requalificarse, se investiga la causa y se evalúa el impacto sobre lo preparado desde la última prueba aprobada. La fuente citada es: Capítulo 797 de la USP (2023), calificación del personal; guía de la FDA sobre procesamiento aséptico.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a áreas limpias y técnica aséptica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe técnico de diagnóstico de áreas y técnica, con tabla de resultados y plan de corrección.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar técnica aséptica y su validación, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el informe y arma una tabla con cada resultado, su criterio y si cumple. Evidencia que debe quedar: Registro del paso.","Analiza el diferencial de presión y el número de renovaciones de aire frente a lo que exige la referencia técnica. Evidencia que debe quedar: Registro del paso.","Lista las fallas de técnica observadas y explica qué riesgo crea cada una. Evidencia que debe quedar: Registro del paso.","Decide qué preparaciones pueden continuar mientras se corrige y cuáles deben suspenderse. Evidencia que debe quedar: Registro del paso.","Explica qué le falta a la central para preparar quimioterapia (área, cabina, presión y personal). Evidencia que debe quedar: Registro del paso.","Propón un plan de corrección con responsables y fecha para cada hallazgo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Error: almacenar una preparación de uso inmediato Corrección: el uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles.","Error: improvisar ante una incompatibilidad Corrección: la duda se resuelve con la ficha técnica y el protocolo, no con la costumbre.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar técnica aséptica y su validación en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Técnica aséptica y su validación»?","respuesta":"La técnica aséptica se aprende y se demuestra: el llenado con medio de cultivo, conocido como media fill, es la prueba de que quien prepara puede hacerlo sin contaminar. Se revisa cómo se hace, cada cuánto y qué pasa si falla."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe técnico de diagnóstico de áreas y técnica, con tabla de resultados y plan de corrección.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Técnica aséptica y su validación se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con áreas limpias y técnica aséptica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"FDA · Procesamiento aséptico (simulación con medio de cultivo). Qué es un media fill, con qué frecuencia se hace y qué significa que falle.","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/sterile-drug-products-produced-aseptic-processing-current-good-manufacturing-practice"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente técnica aséptica y su validación en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de técnica aséptica y su validación"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","técnica","aséptica","validación","áreas","limpias"],"mapa":{"centro":"Técnica aséptica y su validación","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Áreas limpias y técnica aséptica","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Diagnóstico de áreas y técnica de una central","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el informe y arma una tabla con cada resultado, su criterio y si cumple.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza el diferencial de presión y el número de renovaciones de aire frente a lo que exige la referencia técnica.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Lista las fallas de técnica observadas y explica qué riesgo crea cada una.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Decide qué preparaciones pueden continuar mientras se corrige y cuáles deben suspenderse.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Explica qué le falta a la central para preparar quimioterapia (área, cabina, presión y personal).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Propón un plan de corrección con responsables y fecha para cada hallazgo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Técnica aséptica y su validación","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de áreas limpias y técnica aséptica: La central de mezclas del Hospital Río Claro (ficticio) recibió su informe de recertificación semestral y una observación de la técnica de dos auxiliares. Datos simulados: antesala (diseño ISO 8) con 1.900.000 partículas de 0,5 µm por metro cúbico; sala de amortiguamiento (diseño ISO 7) con 395.000; cabina de flujo laminar horizontal ISO 5 con 2.800; diferencial de presión entre sala y antesala de 0,008 pulgadas de columna de agua; 32 renovaciones de aire por hora en la sala. Observación: una auxiliar trabaja con los antebrazos dentro de la cabina pero bloquea con la bolsa el aire que llega al punto de inyección; el otro rocía alcohol sobre los viales sin dejar secar y entra a la sala con reloj. La gerencia quiere empezar a preparar quimioterapia el próximo mes en la misma sala. La pregunta que decide esta clase es: El llenado con medio de cultivo (media fill) de un técnico sale turbio durante la incubación. El jefe de la central decide repetir la prueba el próximo semestre y dejar al técnico trabajando mientras tanto. ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es adecuada, porque un solo resultado positivo puede deberse a contaminación del medio de cultivo durante la incubación y no a la técnica.","correcta":false,"retro":"Esa hipótesis se investiga, pero mientras tanto el resultado obliga a actuar como si la técnica hubiera fallado."},{"texto":"Es adecuada si mientras tanto el técnico solo prepara antibióticos, que tienen menos riesgo que las nutriciones parenterales.","correcta":false,"retro":"No hay preparación estéril de bajo riesgo para quien la recibe contaminada."},{"texto":"Es inadecuada: el técnico no prepara hasta reentrenarse y aprobar de nuevo, y se evalúa lo que elaboró desde su última prueba aprobada.","correcta":true,"retro":"Correcto. Un media fill fallido suspende la autorización para elaborar, obliga a investigar la causa y abre una evaluación de impacto."},{"texto":"Es inadecuada solo porque la repetición de la prueba debe hacerse en tres meses y no en seis, según la categoría.","correcta":false,"retro":"El problema no es el plazo de repetición: el técnico sigue preparando con una técnica no demostrada."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 07. Controles ambientales y de personal
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Controles ambientales y de personal$t$
     AND m.title = $u$Gestión de la calidad en la central$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Controles ambientales y de personal$t$, $u$Gestión de la calidad en la central$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Controles ambientales y de personal","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una preparación estéril debe administrarse hoy y la central está en cambio de turno. Lo que está en juego es el criterio de controles ambientales y de personal. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar controles ambientales y de personal con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar controles ambientales y de personal con gestión de la calidad en la central y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar controles ambientales y de personal y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Qué se monitorea y con qué frecuencia: partículas, microbiología de superficies y de aire, huellas de guantes. Los resultados no son un trámite: son la evidencia de que las áreas siguen comportándose como cuando se calificaron."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, controles ambientales y de personal aparece en medio de una decisión que no admite improvisación: una preparación estéril debe administrarse hoy y la central está en cambio de turno. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de gestión de la calidad en la central. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Qué se monitorea y con qué frecuencia: partículas, microbiología de superficies y de aire, huellas de guantes. Los resultados no son un trámite: son la evidencia de que las áreas siguen comportándose como cuando se calificaron.","Una pregunta que se usa para comprobar esta clase es: «¿Cuál es el propósito principal del monitoreo ambiental y de personal en una central de mezclas?» La respuesta correcta se apoya en lo siguiente: Los resultados de partículas, microbiología de aire y superficies y huellas de guantes muestran si el estado de control se mantiene. Su valor está en analizarlos, ver tendencias y actuar. La fuente citada es: Capítulo 797 de la USP (2023), monitoreo ambiental; Anexo 1 de las BPM de la UE (2022).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a gestión de la calidad en la central y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de desviación completo, listo para firma del director técnico.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar controles ambientales y de personal, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe la descripción objetiva de la desviación: qué, dónde, cuándo y quién la detectó. Evidencia que debe quedar: Registro del paso.","Define las acciones de contención inmediatas para el viernes y el fin de semana. Evidencia que debe quedar: Registro del paso.","Analiza el impacto: qué preparaciones y qué pacientes pueden estar afectados, y qué registros consultarías. Evidencia que debe quedar: Registro del paso.","Plantea al menos dos hipótesis de causa y la evidencia que confirmaría o descartaría cada una. Evidencia que debe quedar: Registro del paso.","Propón acciones correctivas y preventivas con responsable, fecha e indicador de eficacia. Evidencia que debe quedar: Registro del paso.","Decide qué condición debe cumplirse para que el técnico vuelva a preparar. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Error: improvisar ante una incompatibilidad Corrección: la duda se resuelve con la ficha técnica y el protocolo, no con la costumbre.","Error: preparar en un área no controlada Corrección: la cabina no compensa un entorno contaminado; el área y el flujo son parte del control.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar controles ambientales y de personal en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Controles ambientales y de personal»?","respuesta":"Qué se monitorea y con qué frecuencia: partículas, microbiología de superficies y de aire, huellas de guantes. Los resultados no son un trámite: son la evidencia de que las áreas siguen comportándose como cuando se calificaron."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de desviación completo, listo para firma del director técnico.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Controles ambientales y de personal se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con gestión de la calidad en la central.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"UE · Anexo 1, monitoreo ambiental. Qué se monitorea, con qué frecuencia y qué hacer cuando un resultado se sale de límite.","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente controles ambientales y de personal en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de controles ambientales y de personal"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","controles","ambientales","personal"],"mapa":{"centro":"Controles ambientales y de personal","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Gestión de la calidad en la central","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Informe de desviación en la central","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe la descripción objetiva de la desviación: qué, dónde, cuándo y quién la detectó.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Define las acciones de contención inmediatas para el viernes y el fin de semana.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza el impacto: qué preparaciones y qué pacientes pueden estar afectados, y qué registros consultarías.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Plantea al menos dos hipótesis de causa y la evidencia que confirmaría o descartaría cada una.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón acciones correctivas y preventivas con responsable, fecha e indicador de eficacia.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Decide qué condición debe cumplirse para que el técnico vuelva a preparar.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Controles ambientales y de personal","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de gestión de la calidad en la central: El viernes a las 16:00, la central de mezclas de la Clínica Valle Alto (ficticia) recibe dos resultados: una placa de contacto de la superficie de trabajo de la cabina ISO 5, del muestreo mensual, con 4 UFC de cocos grampositivos; y la huella de guantes de un técnico, tomada al terminar su prueba de llenado con medio de cultivo, por encima del nivel de acción del programa. Ese técnico preparó en la semana 46 nutriciones parenterales y 120 jeringas de antibiótico (datos simulados). Para el fin de semana hay 30 nutriciones programadas. El jefe de la central te pide el informe de desviación. La pregunta que decide esta clase es: ¿Cuál es el propósito principal del monitoreo ambiental y de personal en una central de mezclas?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Cumplir un requisito documental que el inspector del Invima revisa en cada visita de certificación de la central.","correcta":false,"retro":"Si se ve como trámite, se pierde su valor: los resultados deben analizarse y generar acciones."},{"texto":"Demostrar que cada preparación final es estéril, de modo que no se necesitan otros controles de calidad.","correcta":false,"retro":"El monitoreo no prueba la esterilidad de cada preparación; muestra el estado del ambiente y del personal."},{"texto":"Reemplazar la certificación semestral de las áreas, que deja de ser necesaria si el monitoreo sale bien.","correcta":false,"retro":"La certificación y el monitoreo se complementan; uno no reemplaza al otro."},{"texto":"Aportar evidencia continua de que áreas y personas siguen bajo control, y detectar tendencias antes de una falla.","correcta":true,"retro":"Correcto. El monitoreo es la evidencia de que las áreas y las personas siguen comportándose como cuando se calificaron."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
