  -- 08. Estabilidad, trazabilidad y documentación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Estabilidad, trazabilidad y documentación$t$
     AND m.title = $u$Gestión de la calidad en la central$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Estabilidad, trazabilidad y documentación$t$, $u$Gestión de la calidad en la central$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Estabilidad, trazabilidad y documentación","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una preparación estéril debe administrarse hoy y la central está en cambio de turno. Lo que está en juego es el criterio de estabilidad, trazabilidad y documentación. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar estabilidad, trazabilidad y documentación con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar estabilidad, trazabilidad y documentación con gestión de la calidad en la central y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar estabilidad, trazabilidad y documentación y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Cada preparación debe poder reconstruirse: qué lotes entraron, quién preparó, quién verificó, a qué hora y para qué paciente. Se revisa también cómo se asigna la fecha límite de uso en preparaciones estériles, donde el margen de error es menor."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, estabilidad, trazabilidad y documentación aparece en medio de una decisión que no admite improvisación: una preparación estéril debe administrarse hoy y la central está en cambio de turno. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de gestión de la calidad en la central. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Cada preparación debe poder reconstruirse: qué lotes entraron, quién preparó, quién verificó, a qué hora y para qué paciente. Se revisa también cómo se asigna la fecha límite de uso en preparaciones estériles, donde el margen de error es menor.","Una pregunta que se usa para comprobar esta clase es: «Se prepara una jeringa de cefazolina en una sala limpia (categoría 2), con técnica aséptica, a partir de componentes estériles y sin prueba de esterilidad. La literatura muestra estabilidad química de 30 días refrigerada. ¿Qué fecha límite de uso se asigna en refrigeración?» La respuesta correcta se apoya en lo siguiente: La fecha límite de uso es la menor entre el límite por esterilidad de la categoría y el límite por estabilidad. En categoría 2, con técnica aséptica, componentes estériles y sin prueba de esterilidad, el límite en refrigeración es de 10 días. La fuente citada es: Capítulo 797 de la USP (2023), fechas límite de uso de la categoría 2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a gestión de la calidad en la central y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de desviación completo, listo para firma del director técnico.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar estabilidad, trazabilidad y documentación, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe la descripción objetiva de la desviación: qué, dónde, cuándo y quién la detectó. Evidencia que debe quedar: Registro del paso.","Define las acciones de contención inmediatas para el viernes y el fin de semana. Evidencia que debe quedar: Registro del paso.","Analiza el impacto: qué preparaciones y qué pacientes pueden estar afectados, y qué registros consultarías. Evidencia que debe quedar: Registro del paso.","Plantea al menos dos hipótesis de causa y la evidencia que confirmaría o descartaría cada una. Evidencia que debe quedar: Registro del paso.","Propón acciones correctivas y preventivas con responsable, fecha e indicador de eficacia. Evidencia que debe quedar: Registro del paso.","Decide qué condición debe cumplirse para que el técnico vuelva a preparar. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: preparar en un área no controlada Corrección: la cabina no compensa un entorno contaminado; el área y el flujo son parte del control.","Error: improvisar ante una incompatibilidad Corrección: la duda se resuelve con la ficha técnica y el protocolo, no con la costumbre.","Error: almacenar una preparación de uso inmediato Corrección: el uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar estabilidad, trazabilidad y documentación en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Estabilidad, trazabilidad y documentación»?","respuesta":"Cada preparación debe poder reconstruirse: qué lotes entraron, quién preparó, quién verificó, a qué hora y para qué paciente. Se revisa también cómo se asigna la fecha límite de uso en preparaciones estériles, donde el margen de error es menor."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de desviación completo, listo para firma del director técnico.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Estabilidad, trazabilidad y documentación se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con gestión de la calidad en la central.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"USP · Capítulo 797, fecha límite de uso. Cómo se asigna la fecha límite de uso en preparaciones estériles, donde el margen de error es menor.","url":"https://www.usp.org/compounding/general-chapter-797"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente estabilidad, trazabilidad y documentación en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de estabilidad, trazabilidad y documentación"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","estabilidad","trazabilidad","documentación"],"mapa":{"centro":"Estabilidad, trazabilidad y documentación","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Gestión de la calidad en la central","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Informe de desviación en la central","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe la descripción objetiva de la desviación: qué, dónde, cuándo y quién la detectó.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Define las acciones de contención inmediatas para el viernes y el fin de semana.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza el impacto: qué preparaciones y qué pacientes pueden estar afectados, y qué registros consultarías.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Plantea al menos dos hipótesis de causa y la evidencia que confirmaría o descartaría cada una.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón acciones correctivas y preventivas con responsable, fecha e indicador de eficacia.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Decide qué condición debe cumplirse para que el técnico vuelva a preparar.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Estabilidad, trazabilidad y documentación","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de gestión de la calidad en la central: El viernes a las 16:00, la central de mezclas de la Clínica Valle Alto (ficticia) recibe dos resultados: una placa de contacto de la superficie de trabajo de la cabina ISO 5, del muestreo mensual, con 4 UFC de cocos grampositivos; y la huella de guantes de un técnico, tomada al terminar su prueba de llenado con medio de cultivo, por encima del nivel de acción del programa. Ese técnico preparó en la semana 46 nutriciones parenterales y 120 jeringas de antibiótico (datos simulados). Para el fin de semana hay 30 nutriciones programadas. El jefe de la central te pide el informe de desviación. La pregunta que decide esta clase es: Se prepara una jeringa de cefazolina en una sala limpia (categoría 2), con técnica aséptica, a partir de componentes estériles y sin prueba de esterilidad. La literatura muestra estabilidad química de 30 días refrigerada. ¿Qué fecha límite de uso se asigna en refrigeración?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"30 días, porque la estabilidad química publicada es el dato más específico disponible para esa mezcla.","correcta":false,"retro":"La estabilidad química es solo uno de los dos límites; el de esterilidad es más corto."},{"texto":"10 días: es el límite de esterilidad de la categoría 2 en nevera y es menor que la estabilidad química.","correcta":true,"retro":"Correcto. Se asigna el menor de los dos límites: esterilidad y estabilidad."},{"texto":"24 horas, porque toda preparación sin prueba de esterilidad se clasifica en la categoría 1, sin importar el área donde se elaboró.","correcta":false,"retro":"La categoría depende de dónde y cómo se prepara; en sala limpia puede ser categoría 2 sin prueba de esterilidad."},{"texto":"45 días, porque la refrigeración prolonga el límite de esterilidad de la categoría 2 hasta ese plazo.","correcta":false,"retro":"45 días corresponde a congelación en esa tabla, no a refrigeración."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 09. Mezclas oncológicas y seguridad de quien prepara
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Mezclas oncológicas y seguridad de quien prepara$t$
     AND m.title = $u$Gestión de la calidad en la central$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Mezclas oncológicas y seguridad de quien prepara$t$, $u$Gestión de la calidad en la central$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Mezclas oncológicas y seguridad de quien prepara","texto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, una prescripción llega incompleta y el área de preparación tiene presión de tiempo. Lo que está en juego es el criterio de mezclas oncológicas y seguridad de quien prepara. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar mezclas oncológicas y seguridad de quien prepara con tus propias palabras y reconocer por qué importa en central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad.","Relacionar mezclas oncológicas y seguridad de quien prepara con gestión de la calidad en la central y con las decisiones de el químico farmacéutico del servicio farmacéutico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar mezclas oncológicas y seguridad de quien prepara y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Los citostáticos exigen proteger también a quien los manipula: contención, equipo de protección, manejo de derrames y de residuos. Esta clase cierra el curso con lo que suele quedar fuera de los manuales de producto."},{"icono":"ShieldCheck","termino":"Preparación estéril","definicion":"Una preparación que debe quedar libre de microorganismos viables y de partículas, porque se administra por una vía que no tiene barreras defensivas."},{"icono":"FileCheck","termino":"Técnica aséptica","definicion":"El conjunto de gestos, áreas, vestimenta y controles que evitan introducir contaminación durante la preparación."},{"icono":"Network","termino":"Validación","definicion":"La evidencia documentada de que un proceso, una limpieza o un método produce de forma consistente el resultado esperado."},{"icono":"ClipboardCheck","termino":"Trazabilidad","definicion":"El registro que permite reconstruir quién preparó, con qué componentes, en qué área y con qué controles."},{"icono":"RefreshCw","termino":"Estabilidad","definicion":"El tiempo durante el cual la preparación conserva su calidad dentro de las condiciones de conservación definidas."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una central de mezclas o un servicio farmacéutico hospitalario colombiano, mezclas oncológicas y seguridad de quien prepara aparece en medio de una decisión que no admite improvisación: una prescripción llega incompleta y el área de preparación tiene presión de tiempo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de gestión de la calidad en la central. El objetivo del curso es claro: Que entiendas qué protege cada requisito de una central de mezclas y qué pasa cuando uno falla. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Los citostáticos exigen proteger también a quien los manipula: contención, equipo de protección, manejo de derrames y de residuos. Esta clase cierra el curso con lo que suele quedar fuera de los manuales de producto.","Una pregunta que se usa para comprobar esta clase es: «Tras un derrame de 20 mL de ciclofosfamida fuera de la cabina, un auxiliar lo limpió con toallas de papel y alcohol, con un solo par de guantes de nitrilo, y botó las toallas en la caneca común. ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: El manejo de un derrame de un medicamento peligroso exige equipo de protección completo, contención con kit, desactivación, descontaminación, limpieza y residuos peligrosos, además del registro y la evaluación de la exposición. La fuente citada es: Capítulo 800 de la USP, derrames y equipo de protección personal.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a gestión de la calidad en la central y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de desviación completo, listo para firma del director técnico.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar mezclas oncológicas y seguridad de quien prepara, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe la descripción objetiva de la desviación: qué, dónde, cuándo y quién la detectó. Evidencia que debe quedar: Registro del paso.","Define las acciones de contención inmediatas para el viernes y el fin de semana. Evidencia que debe quedar: Registro del paso.","Analiza el impacto: qué preparaciones y qué pacientes pueden estar afectados, y qué registros consultarías. Evidencia que debe quedar: Registro del paso.","Plantea al menos dos hipótesis de causa y la evidencia que confirmaría o descartaría cada una. Evidencia que debe quedar: Registro del paso.","Propón acciones correctivas y preventivas con responsable, fecha e indicador de eficacia. Evidencia que debe quedar: Registro del paso.","Decide qué condición debe cumplirse para que el técnico vuelva a preparar. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir estabilidad con esterilidad Corrección: una preparación puede ser estable y estar contaminada; son controles distintos.","Error: rotular después de entregar Corrección: la etiqueta se completa antes de que la preparación salga del área.","Error: preparar en un área no controlada Corrección: la cabina no compensa un entorno contaminado; el área y el flujo son parte del control.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar mezclas oncológicas y seguridad de quien prepara en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"]}],"errores":[{"error":"Preparar en un área no controlada","correccion":"La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."},{"error":"Almacenar una preparación de uso inmediato","correccion":"El uso inmediato tiene un plazo corto y no se convierte en almacenamiento sin área y controles."},{"error":"Rotular después de entregar","correccion":"La etiqueta se completa antes de que la preparación salga del área."},{"error":"Confundir estabilidad con esterilidad","correccion":"Una preparación puede ser estable y estar contaminada; son controles distintos."},{"error":"Improvisar ante una incompatibilidad","correccion":"La duda se resuelve con la ficha técnica y el protocolo, no con la costumbre."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Mezclas oncológicas y seguridad de quien prepara»?","respuesta":"Los citostáticos exigen proteger también a quien los manipula: contención, equipo de protección, manejo de derrames y de residuos. Esta clase cierra el curso con lo que suele quedar fuera de los manuales de producto."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de desviación completo, listo para firma del director técnico.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Preparar en un área no controlada La cabina no compensa un entorno contaminado; el área y el flujo son parte del control."}],"resumen":["Mezclas oncológicas y seguridad de quien prepara se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con gestión de la calidad en la central.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué control demuestra que la preparación siguió el proceso y llegó al paciente correcto?"],"referencias":[{"cita":"OMS · Informe 32, Anexo 2 (productos peligrosos). Contención, protección y manejo de residuos cuando el producto es peligroso para quien lo manipula.","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"},{"cita":"INVIMA. Normograma sanitario.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Buenas prácticas de fabricación de productos estériles.","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente mezclas oncológicas y seguridad de quien prepara en una central de mezclas o un servicio farmacéutico hospitalario colombiano.","alt":"Ilustración de mezclas oncológicas y seguridad de quien prepara"}],"keywords":["central","mezclas","preparaciones","estériles","gestión","calidad","oncológicas","seguridad","quien","prepara"],"mapa":{"centro":"Mezclas oncológicas y seguridad de quien prepara","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Servicio farmacéutico","Gestión de la calidad en la central","Preparación estéril"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Preparar en un área no controlada","Almacenar una preparación de uso inmediato","Rotular después de entregar"]}]},"proceso":{"titulo":"Cómo se aplica: Informe de desviación en la central","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe la descripción objetiva de la desviación: qué, dónde, cuándo y quién la detectó.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Define las acciones de contención inmediatas para el viernes y el fin de semana.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza el impacto: qué preparaciones y qué pacientes pueden estar afectados, y qué registros consultarías.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Plantea al menos dos hipótesis de causa y la evidencia que confirmaría o descartaría cada una.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón acciones correctivas y preventivas con responsable, fecha e indicador de eficacia.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Decide qué condición debe cumplirse para que el técnico vuelva a preparar.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Mezclas oncológicas y seguridad de quien prepara","contexto":"En una central de mezclas o un servicio farmacéutico hospitalario colombiano, el equipo analiza este caso de gestión de la calidad en la central: El viernes a las 16:00, la central de mezclas de la Clínica Valle Alto (ficticia) recibe dos resultados: una placa de contacto de la superficie de trabajo de la cabina ISO 5, del muestreo mensual, con 4 UFC de cocos grampositivos; y la huella de guantes de un técnico, tomada al terminar su prueba de llenado con medio de cultivo, por encima del nivel de acción del programa. Ese técnico preparó en la semana 46 nutriciones parenterales y 120 jeringas de antibiótico (datos simulados). Para el fin de semana hay 30 nutriciones programadas. El jefe de la central te pide el informe de desviación. La pregunta que decide esta clase es: Tras un derrame de 20 mL de ciclofosfamida fuera de la cabina, un auxiliar lo limpió con toallas de papel y alcohol, con un solo par de guantes de nitrilo, y botó las toallas en la caneca común. ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Adecuada, porque se limpió de inmediato y el alcohol al 70 % desinfecta la superficie y arrastra el residuo del citostático.","correcta":false,"retro":"Desinfectar no es descontaminar: el alcohol no inactiva el citostático y puede dispersarlo."},{"texto":"Inadecuada: faltaron protección completa, kit de derrames y residuo peligroso; además se documenta y se valora la exposición.","correcta":true,"retro":"Correcto. Un derrame de peligroso exige doble guante de quimioterapia, bata impermeable, protección ocular y respiratoria, contención con el kit y residuo peligroso, y se valora a la persona expuesta."},{"texto":"Inadecuada solo en el residuo: las toallas debían ir a la caneca de reciclaje, pero la limpieza con alcohol fue correcta.","correcta":false,"retro":"El reciclaje no aplica a residuos contaminados con citostáticos, y el alcohol no descontamina."},{"texto":"Adecuada, porque 20 mL es un volumen pequeño que no exige kit de derrames ni protección distinta de la habitual del servicio.","correcta":false,"retro":"No hay un volumen de citostático que permita omitir el procedimiento de derrames."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases completas con experiencia interactiva (catálogo).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;
  RAISE NOTICE 'Experiencias de %: % clases.', $t$Central de Mezclas: Preparaciones Estériles, BPE y Gestión de la Calidad$t$, v_n;
END $curso$;

-- ============================================================
--  Experiencias de clase: Asuntos Regulatorios Sanitarios ante INVIMA
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  9 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Asuntos Regulatorios Sanitarios ante INVIMA$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Asuntos Regulatorios Sanitarios ante INVIMA$t$;
    RETURN;
  END IF;

  -- 01. Qué es el INVIMA y qué vigila
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Qué es el INVIMA y qué vigila$t$
     AND m.title = $u$El sistema sanitario colombiano$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Qué es el INVIMA y qué vigila$t$, $u$El sistema sanitario colombiano$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Qué es el INVIMA y qué vigila","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de qué es el INVIMA y qué vigila. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar qué es el INVIMA y qué vigila con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar qué es el INVIMA y qué vigila con el sistema sanitario colombiano y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar qué es el INVIMA y qué vigila y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El INVIMA es la autoridad sanitaria nacional y vigila medicamentos, dispositivos médicos, alimentos, cosméticos y productos de aseo, entre otros. Entender su alcance y su relación con el Ministerio de Salud evita el error más común: tocar la puerta equivocada."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, qué es el INVIMA y qué vigila aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de el sistema sanitario colombiano. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El INVIMA es la autoridad sanitaria nacional y vigila medicamentos, dispositivos médicos, alimentos, cosméticos y productos de aseo, entre otros. Entender su alcance y su relación con el Ministerio de Salud evita el error más común: tocar la puerta equivocada.","Una pregunta que se usa para comprobar esta clase es: «¿Cómo se reparten las funciones entre el Ministerio de Salud y Protección Social y el Invima en materia de medicamentos?» La respuesta correcta se apoya en lo siguiente: El Ministerio de Salud y Protección Social formula la política y expide la regulación; el Invima, creado por la Ley 100 de 1993, ejecuta: concede registros sanitarios, certifica buenas prácticas y ejerce inspección, vigilancia y control. La fuente citada es: Ley 100 de 1993, artículo 245; portal institucional del Invima.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a el sistema sanitario colombiano y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de ruta regulatoria con tabla de clasificación y análisis de riesgo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar qué es el INVIMA y qué vigila, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe, para cada producto, su composición y lo que declara. Evidencia que debe quedar: Registro del paso.","Clasifica cada producto: medicamento, producto fitoterapéutico, suplemento dietario, cosmético o dispositivo médico. Evidencia que debe quedar: Registro del paso.","Identifica la norma que rige cada categoría y el tipo de autorización (registro sanitario, notificación sanitaria obligatoria u otra) con su cita. Evidencia que debe quedar: Registro del paso.","Señala qué dato tendrías que verificar en una fuente oficial antes de radicar cada trámite (por ejemplo, un listado o una clase de riesgo). Evidencia que debe quedar: Registro del paso.","Analiza qué pasaría con el producto 3 si la frase dijera «previene la osteoporosis». Evidencia que debe quedar: Registro del paso.","Elige el producto con mayor riesgo de clasificarse mal y explica por qué. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar qué es el INVIMA y qué vigila en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Qué es el INVIMA y qué vigila»?","respuesta":"El INVIMA es la autoridad sanitaria nacional y vigila medicamentos, dispositivos médicos, alimentos, cosméticos y productos de aseo, entre otros. Entender su alcance y su relación con el Ministerio de Salud evita el error más común: tocar la puerta equivocada."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de ruta regulatoria con tabla de clasificación y análisis de riesgo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Qué es el INVIMA y qué vigila se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con el sistema sanitario colombiano.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA · Portal institucional. La autoridad sanitaria colombiana: qué productos vigila y qué trámites ofrece.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente qué es el INVIMA y qué vigila en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de qué es el INVIMA y qué vigila"}],"keywords":["asuntos","regulatorios","sanitarios","invima","vigila","sistema","sanitario","colombiano"],"mapa":{"centro":"Qué es el INVIMA y qué vigila","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","El sistema sanitario colombiano","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Ruta regulatoria de cinco productos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe, para cada producto, su composición y lo que declara.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada producto: medicamento, producto fitoterapéutico, suplemento dietario, cosmético o dispositivo médico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Identifica la norma que rige cada categoría y el tipo de autorización (registro sanitario, notificación sanitaria obligatoria u otra) con su cita.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué dato tendrías que verificar en una fuente oficial antes de radicar cada trámite (por ejemplo, un listado o una clase de riesgo).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Analiza qué pasaría con el producto 3 si la frase dijera «previene la osteoporosis».","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Elige el producto con mayor riesgo de clasificarse mal y explica por qué.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Qué es el INVIMA y qué vigila","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de el sistema sanitario colombiano: Laboratorios Andinos S. A. S. (ficticio), de Bogotá, quiere lanzar en el próximo año cinco productos y te pide la ruta regulatoria de cada uno: (1) tabletas de ibuprofeno de 400 mg; (2) jarabe con extracto de hojas de hiedra, con indicación expectorante; (3) cápsulas de vitamina D3 de 1.000 UI con la frase «apoya la salud de tus huesos»; (4) crema hidratante corporal con urea al 5 %; (5) termómetro digital de uso doméstico. La gerencia quiere saber qué autorización necesita cada uno, ante quién y con qué norma, y cuál representa el mayor riesgo de clasificarse mal (datos simulados). La pregunta que decide esta clase es: ¿Cómo se reparten las funciones entre el Ministerio de Salud y Protección Social y el Invima en materia de medicamentos?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"El Invima expide los decretos sobre medicamentos y el Ministerio de Salud solo se encarga de publicarlos en el Diario Oficial.","correcta":false,"retro":"Los decretos y resoluciones generales los expide el Gobierno y el Ministerio; el Invima ejecuta."},{"texto":"El Invima vigila solo los medicamentos; los alimentos y los cosméticos los vigila el Ministerio de Comercio.","correcta":false,"retro":"El Invima vigila también alimentos, cosméticos, dispositivos médicos y otros productos de uso humano."},{"texto":"El Ministerio fija la política y expide la regulación; el Invima la ejecuta: otorga registros, certifica y vigila.","correcta":true,"retro":"Correcto. Conocer esta división evita tocar la puerta equivocada en un trámite."},{"texto":"Son la misma entidad con dos nombres, uno técnico y otro administrativo, que responden igual a cualquier trámite.","correcta":false,"retro":"Son entidades distintas: el Invima es un establecimiento público adscrito al Ministerio."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Cómo se clasifica un producto
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Cómo se clasifica un producto$t$
     AND m.title = $u$El sistema sanitario colombiano$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Cómo se clasifica un producto$t$, $u$El sistema sanitario colombiano$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cómo se clasifica un producto","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de cómo se clasifica un producto. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar cómo se clasifica un producto con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar cómo se clasifica un producto con el sistema sanitario colombiano y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar cómo se clasifica un producto y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Antes de cualquier trámite hay que responder qué es el producto: medicamento, fitoterapéutico, suplemento dietario, cosmético o dispositivo. La clasificación determina la norma, los requisitos y los tiempos, y clasificarlo mal puede costar meses."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, cómo se clasifica un producto aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de el sistema sanitario colombiano. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Antes de cualquier trámite hay que responder qué es el producto: medicamento, fitoterapéutico, suplemento dietario, cosmético o dispositivo. La clasificación determina la norma, los requisitos y los tiempos, y clasificarlo mal puede costar meses.","Una pregunta que se usa para comprobar esta clase es: «Una empresa vende cápsulas con extracto de una planta y en la etiqueta dice: «mejora la memoria y previene la demencia». Quiere registrarlas como suplemento dietario porque el trámite le parece más sencillo. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: La clasificación depende de la composición y de lo que el producto declara. Los suplementos dietarios no pueden atribuirse propiedades terapéuticas ni preventivas de enfermedades; esa declaración lleva el producto a otra categoría con sus propios requisitos. La fuente citada es: Decreto 3249 de 2006 (suplementos dietarios); Decreto 1156 de 2018 (productos fitoterapéuticos).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a el sistema sanitario colombiano y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de ruta regulatoria con tabla de clasificación y análisis de riesgo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar cómo se clasifica un producto, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe, para cada producto, su composición y lo que declara. Evidencia que debe quedar: Registro del paso.","Clasifica cada producto: medicamento, producto fitoterapéutico, suplemento dietario, cosmético o dispositivo médico. Evidencia que debe quedar: Registro del paso.","Identifica la norma que rige cada categoría y el tipo de autorización (registro sanitario, notificación sanitaria obligatoria u otra) con su cita. Evidencia que debe quedar: Registro del paso.","Señala qué dato tendrías que verificar en una fuente oficial antes de radicar cada trámite (por ejemplo, un listado o una clase de riesgo). Evidencia que debe quedar: Registro del paso.","Analiza qué pasaría con el producto 3 si la frase dijera «previene la osteoporosis». Evidencia que debe quedar: Registro del paso.","Elige el producto con mayor riesgo de clasificarse mal y explica por qué. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar cómo se clasifica un producto en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Cómo se clasifica un producto»?","respuesta":"Antes de cualquier trámite hay que responder qué es el producto: medicamento, fitoterapéutico, suplemento dietario, cosmético o dispositivo. La clasificación determina la norma, los requisitos y los tiempos, y clasificarlo mal puede costar meses."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de ruta regulatoria con tabla de clasificación y análisis de riesgo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Cómo se clasifica un producto se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con el sistema sanitario colombiano.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Decreto 677 de 1995 · Ámbito de aplicación. Qué es medicamento y qué no, y por qué de esa definición depende todo el trámite.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente cómo se clasifica un producto en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de cómo se clasifica un producto"}],"keywords":["asuntos","regulatorios","sanitarios","invima","clasifica","producto","sistema","sanitario","colombiano"],"mapa":{"centro":"Cómo se clasifica un producto","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","El sistema sanitario colombiano","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Ruta regulatoria de cinco productos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe, para cada producto, su composición y lo que declara.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada producto: medicamento, producto fitoterapéutico, suplemento dietario, cosmético o dispositivo médico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Identifica la norma que rige cada categoría y el tipo de autorización (registro sanitario, notificación sanitaria obligatoria u otra) con su cita.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué dato tendrías que verificar en una fuente oficial antes de radicar cada trámite (por ejemplo, un listado o una clase de riesgo).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Analiza qué pasaría con el producto 3 si la frase dijera «previene la osteoporosis».","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Elige el producto con mayor riesgo de clasificarse mal y explica por qué.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Cómo se clasifica un producto","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de el sistema sanitario colombiano: Laboratorios Andinos S. A. S. (ficticio), de Bogotá, quiere lanzar en el próximo año cinco productos y te pide la ruta regulatoria de cada uno: (1) tabletas de ibuprofeno de 400 mg; (2) jarabe con extracto de hojas de hiedra, con indicación expectorante; (3) cápsulas de vitamina D3 de 1.000 UI con la frase «apoya la salud de tus huesos»; (4) crema hidratante corporal con urea al 5 %; (5) termómetro digital de uso doméstico. La gerencia quiere saber qué autorización necesita cada uno, ante quién y con qué norma, y cuál representa el mayor riesgo de clasificarse mal (datos simulados). La pregunta que decide esta clase es: Una empresa vende cápsulas con extracto de una planta y en la etiqueta dice: «mejora la memoria y previene la demencia». Quiere registrarlas como suplemento dietario porque el trámite le parece más sencillo. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es un suplemento dietario, porque se trata de un extracto vegetal presentado en cápsulas para consumo oral diario.","correcta":false,"retro":"La forma de presentación no define la categoría: la definen la composición y lo que el producto declara hacer."},{"texto":"Es un alimento, porque se vende en tiendas naturistas y no requiere fórmula médica para su compra.","correcta":false,"retro":"El canal de venta no clasifica el producto. Las declaraciones de salud sí."},{"texto":"Puede ser suplemento si elimina la palabra «demencia» y conserva «previene» para no alarmar al comprador.","correcta":false,"retro":"Cualquier declaración de prevenir o tratar una enfermedad es terapéutica, con o sin esa palabra."},{"texto":"Prevenir una enfermedad es una declaración terapéutica: no cabe como suplemento y debe evaluarse otra figura.","correcta":true,"retro":"Correcto. Un suplemento no puede atribuirse propiedades terapéuticas; con esa declaración, la ruta es fitoterapéutico o medicamento."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. El Decreto 677 de 1995 y sus actualizaciones
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$El Decreto 677 de 1995 y sus actualizaciones$t$
     AND m.title = $u$El sistema sanitario colombiano$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$El Decreto 677 de 1995 y sus actualizaciones$t$, $u$El sistema sanitario colombiano$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El Decreto 677 de 1995 y sus actualizaciones","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de el Decreto 677 de 1995 y sus actualizaciones. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar el Decreto 677 de 1995 y sus actualizaciones con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar el Decreto 677 de 1995 y sus actualizaciones con el sistema sanitario colombiano y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar el Decreto 677 de 1995 y sus actualizaciones y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El Decreto 677 de 1995 es el régimen de registros sanitarios de medicamentos y productos afines. Se revisa su estructura y las normas que lo han ido actualizando, para saber dónde buscar cuando aparece una duda."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, el Decreto 677 de 1995 y sus actualizaciones aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de el sistema sanitario colombiano. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El Decreto 677 de 1995 es el régimen de registros sanitarios de medicamentos y productos afines. Se revisa su estructura y las normas que lo han ido actualizando, para saber dónde buscar cuando aparece una duda.","Una pregunta que se usa para comprobar esta clase es: «Para resolver una duda sobre requisitos de un registro, un analista consulta solo el texto original del Decreto 677 de 1995 que descargó hace años. ¿Cuál es la valoración más acertada?» La respuesta correcta se apoya en lo siguiente: El Decreto 677 de 1995 es la base del régimen de registros, pero ha cambiado mucho: el Decreto 334 de 2022 derogó su artículo 18 (modificaciones) y el Decreto 1474 de 2023 volvió indefinida la vigencia de los registros de medicamentos. La consulta responsable usa la versión vigente, por ejemplo en el normograma del Invima. La fuente citada es: Decreto 677 de 1995, versión vigente en el normograma del Invima; Decreto 334 de 2022; Decreto 1474 de 2023.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a el sistema sanitario colombiano y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de ruta regulatoria con tabla de clasificación y análisis de riesgo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar el Decreto 677 de 1995 y sus actualizaciones, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe, para cada producto, su composición y lo que declara. Evidencia que debe quedar: Registro del paso.","Clasifica cada producto: medicamento, producto fitoterapéutico, suplemento dietario, cosmético o dispositivo médico. Evidencia que debe quedar: Registro del paso.","Identifica la norma que rige cada categoría y el tipo de autorización (registro sanitario, notificación sanitaria obligatoria u otra) con su cita. Evidencia que debe quedar: Registro del paso.","Señala qué dato tendrías que verificar en una fuente oficial antes de radicar cada trámite (por ejemplo, un listado o una clase de riesgo). Evidencia que debe quedar: Registro del paso.","Analiza qué pasaría con el producto 3 si la frase dijera «previene la osteoporosis». Evidencia que debe quedar: Registro del paso.","Elige el producto con mayor riesgo de clasificarse mal y explica por qué. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Una empresa emergente de Medellín (ficticia) quiere lanzar una bebida en polvo con colágeno hidrolizado, biotina y extracto de cúrcuma. El borrador de etiqueta dice: «reduce la inflamación de las articulaciones y mejora la piel en 30 días». El equipo de mercadeo pregunta si puede venderla como alimento o suplemento para «salir rápido» y quiere publicitarla con una influenciadora (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar el Decreto 677 de 1995 y sus actualizaciones en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «El Decreto 677 de 1995 y sus actualizaciones»?","respuesta":"El Decreto 677 de 1995 es el régimen de registros sanitarios de medicamentos y productos afines. Se revisa su estructura y las normas que lo han ido actualizando, para saber dónde buscar cuando aparece una duda."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de ruta regulatoria con tabla de clasificación y análisis de riesgo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["El Decreto 677 de 1995 y sus actualizaciones se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con el sistema sanitario colombiano.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Buenas prácticas de fabricación de medicamentos · CEFIIN · 15 min · ATENCIÓN: explica la norma mexicana NOM-059, sirve para comparar con la colombiana","url":"https://www.youtube.com/watch?v=97mTCyv2KgM"},{"cita":"Decreto 677 de 1995 · Régimen de registros sanitarios. La estructura completa de la norma: títulos, capítulos y dónde buscar cada cosa.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente el Decreto 677 de 1995 y sus actualizaciones en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de el Decreto 677 de 1995 y sus actualizaciones"}],"keywords":["asuntos","regulatorios","sanitarios","invima","decreto","actualizaciones","sistema","sanitario","colombiano"],"mapa":{"centro":"El Decreto 677 de 1995 y sus actualizaciones","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","El sistema sanitario colombiano","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Ruta regulatoria de cinco productos","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe, para cada producto, su composición y lo que declara.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada producto: medicamento, producto fitoterapéutico, suplemento dietario, cosmético o dispositivo médico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Identifica la norma que rige cada categoría y el tipo de autorización (registro sanitario, notificación sanitaria obligatoria u otra) con su cita.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala qué dato tendrías que verificar en una fuente oficial antes de radicar cada trámite (por ejemplo, un listado o una clase de riesgo).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Analiza qué pasaría con el producto 3 si la frase dijera «previene la osteoporosis».","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Elige el producto con mayor riesgo de clasificarse mal y explica por qué.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"El Decreto 677 de 1995 y sus actualizaciones","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de el sistema sanitario colombiano: Laboratorios Andinos S. A. S. (ficticio), de Bogotá, quiere lanzar en el próximo año cinco productos y te pide la ruta regulatoria de cada uno: (1) tabletas de ibuprofeno de 400 mg; (2) jarabe con extracto de hojas de hiedra, con indicación expectorante; (3) cápsulas de vitamina D3 de 1.000 UI con la frase «apoya la salud de tus huesos»; (4) crema hidratante corporal con urea al 5 %; (5) termómetro digital de uso doméstico. La gerencia quiere saber qué autorización necesita cada uno, ante quién y con qué norma, y cuál representa el mayor riesgo de clasificarse mal (datos simulados). La pregunta que decide esta clase es: Para resolver una duda sobre requisitos de un registro, un analista consulta solo el texto original del Decreto 677 de 1995 que descargó hace años. ¿Cuál es la valoración más acertada?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es suficiente: un decreto no cambia una vez expedido, y el texto original es la fuente más confiable.","correcta":false,"retro":"Los decretos se modifican, se derogan parcialmente y se complementan con normas posteriores."},{"texto":"Es riesgosa: debe consultar la versión vigente y compilada, y las normas posteriores que lo modifican o complementan.","correcta":true,"retro":"Correcto. Un texto desactualizado lleva a radicar con requisitos que ya no existen o a omitir los nuevos."},{"texto":"Es suficiente si además revisa una guía de la OMS, que prevalece sobre la norma colombiana cuando hay alguna diferencia entre ambas.","correcta":false,"retro":"Las guías internacionales orientan, pero no prevalecen sobre la norma colombiana vigente."},{"texto":"Es riesgosa solo porque los trámites ya no se rigen por decretos sino por circulares internas del Invima.","correcta":false,"retro":"Los decretos siguen rigiendo; las circulares y guías orientan su aplicación."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 04. Qué lleva el expediente
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Qué lleva el expediente$t$
     AND m.title = $u$El registro sanitario, paso a paso$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Qué lleva el expediente$t$, $u$El registro sanitario, paso a paso$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Qué lleva el expediente","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de qué lleva el expediente. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar qué lleva el expediente con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar qué lleva el expediente con el registro sanitario, paso a paso y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar qué lleva el expediente y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Documentación legal, técnica y de calidad: fórmula cuantitativa, proceso de fabricación, métodos analíticos, estudios de estabilidad, arte de empaque y certificado de BPM del fabricante. Se revisa qué se pide y por qué cada pieza importa."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, qué lleva el expediente aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de el registro sanitario, paso a paso. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Documentación legal, técnica y de calidad: fórmula cuantitativa, proceso de fabricación, métodos analíticos, estudios de estabilidad, arte de empaque y certificado de BPM del fabricante. Se revisa qué se pide y por qué cada pieza importa.","Una pregunta que se usa para comprobar esta clase es: «El expediente de un genérico trae fórmula, métodos analíticos validados y certificado de buenas prácticas del fabricante, pero los estudios de estabilidad se hicieron en un envase distinto del que se comercializará. ¿Qué consecuencia tiene ese vacío?» La respuesta correcta se apoya en lo siguiente: La vida útil se sustenta con estabilidad del producto en su envase de comercialización. Si el envase cambia, el dato no es transferible sin justificación, y la evaluación farmacéutica lo cuestionará. La fuente citada es: Decreto 677 de 1995, documentación técnica del registro; guía ICH Q1A(R2) como referencia técnica de estabilidad.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a el registro sanitario, paso a paso y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de respuesta al requerimiento: matriz, carta y recomendación.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar qué lleva el expediente, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el requerimiento y copia cada punto en una matriz con columnas: punto, evidencia disponible, brecha, responsable y fecha. Evidencia que debe quedar: Registro del paso.","Para cada punto, decide si la evidencia existe, si puede generarse antes del vencimiento o si no. Evidencia que debe quedar: Registro del paso.","Analiza si la estabilidad a 6 meses permite sostener la vida útil propuesta o si conviene ajustarla. Evidencia que debe quedar: Registro del paso.","Evalúa las alternativas para los puntos sin evidencia, sabiendo que el requerimiento se hace por una sola vez: responder con lo que existe y asumir el riesgo, o desistir y radicar de nuevo. Evidencia que debe quedar: Registro del paso.","Redacta la carta de respuesta con la estructura punto por punto (máximo una página) y el índice de anexos. Evidencia que debe quedar: Registro del paso.","Escribe una recomendación para la gerencia con la alternativa elegida y su riesgo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Farmacéutica del Caribe (ficticia) recibió un requerimiento sobre el registro de un genérico. La analista que llevaba el trámite renunció y el requerimiento apareció en su correo cuando faltaban tres días para el vencimiento. Pide: la validación del método de disolución, la estabilidad en el envase de comercialización y una corrección del arte de la etiqueta. La validación del método nunca se hizo; la estabilidad existe; el arte se corrige en un día (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar qué lleva el expediente en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Qué lleva el expediente»?","respuesta":"Documentación legal, técnica y de calidad: fórmula cuantitativa, proceso de fabricación, métodos analíticos, estudios de estabilidad, arte de empaque y certificado de BPM del fabricante. Se revisa qué se pide y por qué cada pieza importa."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de respuesta al requerimiento: matriz, carta y recomendación.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Qué lleva el expediente se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con el registro sanitario, paso a paso.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Decreto 677 de 1995 · Requisitos del registro sanitario. Documentación legal, técnica y de calidad que exige el expediente.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente qué lleva el expediente en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de qué lleva el expediente"}],"keywords":["asuntos","regulatorios","sanitarios","invima","lleva","expediente","registro","sanitario"],"mapa":{"centro":"Qué lleva el expediente","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","El registro sanitario, paso a paso","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Plan de respuesta a un requerimiento","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el requerimiento y copia cada punto en una matriz con columnas: punto, evidencia disponible, brecha, responsable y fecha.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para cada punto, decide si la evidencia existe, si puede generarse antes del vencimiento o si no.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza si la estabilidad a 6 meses permite sostener la vida útil propuesta o si conviene ajustarla.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Evalúa las alternativas para los puntos sin evidencia, sabiendo que el requerimiento se hace por una sola vez: responder con lo que existe y asumir el riesgo, o desistir y radicar de nuevo.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la carta de respuesta con la estructura punto por punto (máximo una página) y el índice de anexos.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Escribe una recomendación para la gerencia con la alternativa elegida y su riesgo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Qué lleva el expediente","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de el registro sanitario, paso a paso: Medicamentos del Pacífico S. A. S. (ficticia), de Cali, radicó la solicitud de registro sanitario de un genérico importado en la modalidad importar y vender. Hoy recibió un requerimiento con cuatro puntos: (1) estudios de estabilidad en el envase de comercialización, porque los presentados usaron otro envase; (2) informe de validación del método de disolución; (3) corrección del arte de la etiqueta, que omite el número de lote y la fecha de vencimiento; (4) certificado de buenas prácticas de manufactura del fabricante extranjero vigente, porque el aportado venció hace dos meses. La empresa tiene la estabilidad en el envase correcto a 6 meses, la validación del método está en curso y el fabricante dice que su nueva certificación saldrá «en unas semanas» (datos simulados). La pregunta que decide esta clase es: El expediente de un genérico trae fórmula, métodos analíticos validados y certificado de buenas prácticas del fabricante, pero los estudios de estabilidad se hicieron en un envase distinto del que se comercializará. ¿Qué consecuencia tiene ese vacío?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Ninguna, porque la estabilidad depende del principio activo y no del material de envase.","correcta":false,"retro":"El envase protege de la humedad, la luz y el oxígeno: cambiarlo puede cambiar la estabilidad."},{"texto":"El expediente se rechaza de plano, sin posibilidad de requerimiento, porque falta un documento legal obligatorio del expediente.","correcta":false,"retro":"La estabilidad es un soporte técnico, no legal, y su vacío suele dar lugar a un requerimiento."},{"texto":"La vida útil propuesta no queda sustentada para el envase real; la evaluación farmacéutica pedirá esa estabilidad.","correcta":true,"retro":"Correcto. Cada dato de la vida útil debe corresponder al producto en su envase de comercialización."},{"texto":"Solo afecta la etiqueta, que deberá decir «sin datos de estabilidad» mientras se completan los estudios.","correcta":false,"retro":"No existe esa leyenda: sin sustento no se aprueba la vida útil propuesta."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 05. Evaluación farmacológica y farmacéutica
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Evaluación farmacológica y farmacéutica$t$
     AND m.title = $u$El registro sanitario, paso a paso$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Evaluación farmacológica y farmacéutica$t$, $u$El registro sanitario, paso a paso$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Evaluación farmacológica y farmacéutica","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de evaluación farmacológica y farmacéutica. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar evaluación farmacológica y farmacéutica con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar evaluación farmacológica y farmacéutica con el registro sanitario, paso a paso y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar evaluación farmacológica y farmacéutica y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Son dos evaluaciones distintas y a veces consecutivas: la farmacológica mira el principio activo y su relación beneficio-riesgo, la farmacéutica mira la calidad del producto propuesto. Saber cuál aplica evita radicar un trámite incompleto."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, evaluación farmacológica y farmacéutica aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de el registro sanitario, paso a paso. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Son dos evaluaciones distintas y a veces consecutivas: la farmacológica mira el principio activo y su relación beneficio-riesgo, la farmacéutica mira la calidad del producto propuesto. Saber cuál aplica evita radicar un trámite incompleto.","Una pregunta que se usa para comprobar esta clase es: «¿Qué diferencia hay entre la evaluación farmacológica y la evaluación farmacéutica de un medicamento?» La respuesta correcta se apoya en lo siguiente: La evaluación farmacológica se forma un juicio sobre la utilidad, conveniencia y seguridad del medicamento; la farmacéutica conceptúa sobre la capacidad técnica del fabricante, el proceso de fabricación y la calidad del producto. La fuente citada es: Decreto 677 de 1995, evaluación farmacológica y evaluación farmacéutica.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a el registro sanitario, paso a paso y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de respuesta al requerimiento: matriz, carta y recomendación.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar evaluación farmacológica y farmacéutica, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el requerimiento y copia cada punto en una matriz con columnas: punto, evidencia disponible, brecha, responsable y fecha. Evidencia que debe quedar: Registro del paso.","Para cada punto, decide si la evidencia existe, si puede generarse antes del vencimiento o si no. Evidencia que debe quedar: Registro del paso.","Analiza si la estabilidad a 6 meses permite sostener la vida útil propuesta o si conviene ajustarla. Evidencia que debe quedar: Registro del paso.","Evalúa las alternativas para los puntos sin evidencia, sabiendo que el requerimiento se hace por una sola vez: responder con lo que existe y asumir el riesgo, o desistir y radicar de nuevo. Evidencia que debe quedar: Registro del paso.","Redacta la carta de respuesta con la estructura punto por punto (máximo una página) y el índice de anexos. Evidencia que debe quedar: Registro del paso.","Escribe una recomendación para la gerencia con la alternativa elegida y su riesgo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar evaluación farmacológica y farmacéutica en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Evaluación farmacológica y farmacéutica»?","respuesta":"Son dos evaluaciones distintas y a veces consecutivas: la farmacológica mira el principio activo y su relación beneficio-riesgo, la farmacéutica mira la calidad del producto propuesto. Saber cuál aplica evita radicar un trámite incompleto."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de respuesta al requerimiento: matriz, carta y recomendación.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Evaluación farmacológica y farmacéutica se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con el registro sanitario, paso a paso.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Decreto 677 de 1995 · Evaluaciones. Las dos evaluaciones, qué mira cada una y cuándo aplica cada cual.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente evaluación farmacológica y farmacéutica en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de evaluación farmacológica y farmacéutica"}],"keywords":["asuntos","regulatorios","sanitarios","invima","evaluación","farmacológica","farmacéutica","registro","sanitario"],"mapa":{"centro":"Evaluación farmacológica y farmacéutica","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","El registro sanitario, paso a paso","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Plan de respuesta a un requerimiento","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el requerimiento y copia cada punto en una matriz con columnas: punto, evidencia disponible, brecha, responsable y fecha.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para cada punto, decide si la evidencia existe, si puede generarse antes del vencimiento o si no.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza si la estabilidad a 6 meses permite sostener la vida útil propuesta o si conviene ajustarla.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Evalúa las alternativas para los puntos sin evidencia, sabiendo que el requerimiento se hace por una sola vez: responder con lo que existe y asumir el riesgo, o desistir y radicar de nuevo.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la carta de respuesta con la estructura punto por punto (máximo una página) y el índice de anexos.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Escribe una recomendación para la gerencia con la alternativa elegida y su riesgo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Evaluación farmacológica y farmacéutica","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de el registro sanitario, paso a paso: Medicamentos del Pacífico S. A. S. (ficticia), de Cali, radicó la solicitud de registro sanitario de un genérico importado en la modalidad importar y vender. Hoy recibió un requerimiento con cuatro puntos: (1) estudios de estabilidad en el envase de comercialización, porque los presentados usaron otro envase; (2) informe de validación del método de disolución; (3) corrección del arte de la etiqueta, que omite el número de lote y la fecha de vencimiento; (4) certificado de buenas prácticas de manufactura del fabricante extranjero vigente, porque el aportado venció hace dos meses. La empresa tiene la estabilidad en el envase correcto a 6 meses, la validación del método está en curso y el fabricante dice que su nueva certificación saldrá «en unas semanas» (datos simulados). La pregunta que decide esta clase es: ¿Qué diferencia hay entre la evaluación farmacológica y la evaluación farmacéutica de un medicamento?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"La farmacológica revisa la calidad del producto y la farmacéutica revisa la publicidad que se hará después de obtener el registro.","correcta":false,"retro":"La publicidad no es objeto de ninguna de las dos evaluaciones del registro."},{"texto":"La farmacológica juzga la utilidad, conveniencia y seguridad del principio activo; la farmacéutica, la calidad del producto.","correcta":true,"retro":"Correcto. Son dos juicios distintos y a veces consecutivos."},{"texto":"Son la misma evaluación con dos nombres; la diferencia está solo en el grupo del Invima que la firma.","correcta":false,"retro":"No son la misma: evalúan objetos distintos con criterios distintos."},{"texto":"La farmacéutica solo aplica a medicamentos importados y la farmacológica a los fabricados en Colombia.","correcta":false,"retro":"El origen del producto no define qué evaluación aplica."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
