  -- 06. Requerimientos y cómo responderlos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Requerimientos y cómo responderlos$t$
     AND m.title = $u$El registro sanitario, paso a paso$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Requerimientos y cómo responderlos$t$, $u$El registro sanitario, paso a paso$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Requerimientos y cómo responderlos","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de requerimientos y cómo responderlos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar requerimientos y cómo responderlos con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar requerimientos y cómo responderlos con el registro sanitario, paso a paso y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar requerimientos y cómo responderlos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Un requerimiento no es un rechazo, pero mal respondido termina siéndolo. Se revisa cómo se lee, qué plazos corren, cómo se construye una respuesta trazable y qué pasa si se vence el término."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, requerimientos y cómo responderlos aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de el registro sanitario, paso a paso. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Un requerimiento no es un rechazo, pero mal respondido termina siéndolo. Se revisa cómo se lee, qué plazos corren, cómo se construye una respuesta trazable y qué pasa si se vence el término.","Una pregunta que se usa para comprobar esta clase es: «Una empresa responde un requerimiento del Invima reenviando el expediente completo con una carta que dice: «adjuntamos la información solicitada». ¿Cuál es la valoración más acertada de esa respuesta?» La respuesta correcta se apoya en lo siguiente: El Invima requiere la información faltante por una sola vez y con un término fijo según el trámite. Por eso la respuesta va punto por punto, con la evidencia de cada uno y su ubicación, coherente con el expediente. Si el término se vence sin respuesta, se entiende que la empresa desiste y se declara el abandono de la solicitud. La fuente citada es: Decreto 677 de 1995, artículos 23, 25 y 29 (requerimiento por una sola vez y abandono).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a el registro sanitario, paso a paso y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de respuesta al requerimiento: matriz, carta y recomendación.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar requerimientos y cómo responderlos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el requerimiento y copia cada punto en una matriz con columnas: punto, evidencia disponible, brecha, responsable y fecha. Evidencia que debe quedar: Registro del paso.","Para cada punto, decide si la evidencia existe, si puede generarse antes del vencimiento o si no. Evidencia que debe quedar: Registro del paso.","Analiza si la estabilidad a 6 meses permite sostener la vida útil propuesta o si conviene ajustarla. Evidencia que debe quedar: Registro del paso.","Evalúa las alternativas para los puntos sin evidencia, sabiendo que el requerimiento se hace por una sola vez: responder con lo que existe y asumir el riesgo, o desistir y radicar de nuevo. Evidencia que debe quedar: Registro del paso.","Redacta la carta de respuesta con la estructura punto por punto (máximo una página) y el índice de anexos. Evidencia que debe quedar: Registro del paso.","Escribe una recomendación para la gerencia con la alternativa elegida y su riesgo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar requerimientos y cómo responderlos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Requerimientos y cómo responderlos»?","respuesta":"Un requerimiento no es un rechazo, pero mal respondido termina siéndolo. Se revisa cómo se lee, qué plazos corren, cómo se construye una respuesta trazable y qué pasa si se vence el término."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de respuesta al requerimiento: matriz, carta y recomendación.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Requerimientos y cómo responderlos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con el registro sanitario, paso a paso.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA · Trámites y servicios. Dónde se consulta el estado de un trámite y cómo se radica una respuesta.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente requerimientos y cómo responderlos en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de requerimientos y cómo responderlos"}],"keywords":["asuntos","regulatorios","sanitarios","invima","requerimientos","responderlos","registro","sanitario"],"mapa":{"centro":"Requerimientos y cómo responderlos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","El registro sanitario, paso a paso","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Plan de respuesta a un requerimiento","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el requerimiento y copia cada punto en una matriz con columnas: punto, evidencia disponible, brecha, responsable y fecha.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para cada punto, decide si la evidencia existe, si puede generarse antes del vencimiento o si no.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza si la estabilidad a 6 meses permite sostener la vida útil propuesta o si conviene ajustarla.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Evalúa las alternativas para los puntos sin evidencia, sabiendo que el requerimiento se hace por una sola vez: responder con lo que existe y asumir el riesgo, o desistir y radicar de nuevo.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la carta de respuesta con la estructura punto por punto (máximo una página) y el índice de anexos.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Escribe una recomendación para la gerencia con la alternativa elegida y su riesgo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Requerimientos y cómo responderlos","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de el registro sanitario, paso a paso: Medicamentos del Pacífico S. A. S. (ficticia), de Cali, radicó la solicitud de registro sanitario de un genérico importado en la modalidad importar y vender. Hoy recibió un requerimiento con cuatro puntos: (1) estudios de estabilidad en el envase de comercialización, porque los presentados usaron otro envase; (2) informe de validación del método de disolución; (3) corrección del arte de la etiqueta, que omite el número de lote y la fecha de vencimiento; (4) certificado de buenas prácticas de manufactura del fabricante extranjero vigente, porque el aportado venció hace dos meses. La empresa tiene la estabilidad en el envase correcto a 6 meses, la validación del método está en curso y el fabricante dice que su nueva certificación saldrá «en unas semanas» (datos simulados). La pregunta que decide esta clase es: Una empresa responde un requerimiento del Invima reenviando el expediente completo con una carta que dice: «adjuntamos la información solicitada». ¿Cuál es la valoración más acertada de esa respuesta?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es adecuada, porque el Invima recibe toda la información y su evaluador puede buscar en ella lo que necesite revisar.","correcta":false,"retro":"Trasladar al evaluador la búsqueda aumenta el riesgo de que el punto se dé por no respondido."},{"texto":"Es adecuada si se envía antes de la mitad del plazo, porque la oportunidad compensa la forma.","correcta":false,"retro":"La oportunidad no compensa una respuesta que no demuestra que cada punto quedó resuelto."},{"texto":"Es inadecuada solo porque la carta debía ir firmada por el representante legal y no por el analista.","correcta":false,"retro":"La firma importa, pero el problema de fondo es que no hay trazabilidad punto por punto."},{"texto":"Es inadecuada: debe responder punto por punto, con la evidencia de cada uno y dónde está, dentro del término.","correcta":true,"retro":"Correcto. Una respuesta trazable muestra qué se pidió, qué se aporta y dónde se encuentra."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 07. Modificaciones y renovaciones
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Modificaciones y renovaciones$t$
     AND m.title = $u$Después del registro$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Modificaciones y renovaciones$t$, $u$Después del registro$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Modificaciones y renovaciones","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de modificaciones y renovaciones. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar modificaciones y renovaciones con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar modificaciones y renovaciones con después del registro y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar modificaciones y renovaciones y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El registro no es un documento que se archiva: cambiar un fabricante, una fórmula, un envase o un arte exige tramitar una modificación. Y el registro vence. Se revisa qué cambios requieren aprobación previa y cuáles solo aviso."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, modificaciones y renovaciones aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de después del registro. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El registro no es un documento que se archiva: cambiar un fabricante, una fórmula, un envase o un arte exige tramitar una modificación. Y el registro vence. Se revisa qué cambios requieren aprobación previa y cuáles solo aviso.","Una pregunta que se usa para comprobar esta clase es: «¿Por qué un cambio de fabricante, de fórmula o de envase exige tramitar una modificación del registro sanitario?» La respuesta correcta se apoya en lo siguiente: El registro sanitario autoriza un producto con una fórmula, un fabricante, un proceso, un envase y una información aprobados. Desde el Decreto 1474 de 2023 su vigencia es indefinida, siempre que se mantengan esas condiciones: por eso los cambios se tramitan como modificación, que hoy regula el Decreto 334 de 2022. La fuente citada es: Decreto 334 de 2022 (modificación de registros sanitarios); Decreto 1474 de 2023 (vigencia indefinida).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a después del registro y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de cumplimiento poscomercialización con calendario, decisiones y prioridades.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar modificaciones y renovaciones, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y separa las cinco situaciones. Evidencia que debe quedar: Registro del paso.","Para el cambio de fabricante del principio activo, define el trámite, la documentación de soporte y si se puede vender con el nuevo fabricante antes de la aprobación. Evidencia que debe quedar: Registro del paso.","Explica al gerente comercial qué significa la vigencia indefinida del registro (Decreto 1474 de 2023) y qué condiciones la sostienen. Evidencia que debe quedar: Registro del paso.","Define qué se hace con los tres reportes: plazos, canal, evaluación de causalidad y análisis de señal. Evidencia que debe quedar: Registro del paso.","Responde a mercadeo sobre el comercial y los influenciadores con la norma aplicable y una alternativa permitida. Evidencia que debe quedar: Registro del paso.","Prepara la lista de verificación para la visita del Invima a la bodega. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar modificaciones y renovaciones en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Modificaciones y renovaciones»?","respuesta":"El registro no es un documento que se archiva: cambiar un fabricante, una fórmula, un envase o un arte exige tramitar una modificación. Y el registro vence. Se revisa qué cambios requieren aprobación previa y cuáles solo aviso."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de cumplimiento poscomercialización con calendario, decisiones y prioridades.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Modificaciones y renovaciones se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con después del registro.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Decreto 677 de 1995 · Modificaciones al registro. Qué cambios exigen aprobación previa, cuáles solo aviso, y cuándo vence el registro.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente modificaciones y renovaciones en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de modificaciones y renovaciones"}],"keywords":["asuntos","regulatorios","sanitarios","invima","modificaciones","renovaciones","después","registro"],"mapa":{"centro":"Modificaciones y renovaciones","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Después del registro","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Plan de cumplimiento poscomercialización","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y separa las cinco situaciones.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para el cambio de fabricante del principio activo, define el trámite, la documentación de soporte y si se puede vender con el nuevo fabricante antes de la aprobación.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Explica al gerente comercial qué significa la vigencia indefinida del registro (Decreto 1474 de 2023) y qué condiciones la sostienen.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Define qué se hace con los tres reportes: plazos, canal, evaluación de causalidad y análisis de señal.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Responde a mercadeo sobre el comercial y los influenciadores con la norma aplicable y una alternativa permitida.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prepara la lista de verificación para la visita del Invima a la bodega.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Modificaciones y renovaciones","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de después del registro: Distribuciones Andes Pharma (ficticia) es titular del registro sanitario de unas tabletas de venta con fórmula médica. En la misma semana ocurre lo siguiente: compras propone cambiar el fabricante del principio activo por uno más barato; llegan tres reportes de eventos adversos, uno de ellos con hospitalización; mercadeo propone un comercial de televisión y una campaña con influenciadores; el gerente comercial afirma que «como el registro ya no vence, no hay que volver a tocarlo»; y el Invima anuncia una visita de inspección a la bodega del importador para el próximo mes (datos simulados). La gerente te pide un plan para no poner en riesgo el registro. La pregunta que decide esta clase es: ¿Por qué un cambio de fabricante, de fórmula o de envase exige tramitar una modificación del registro sanitario?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Porque el registro aprueba un producto en condiciones concretas; cambiarlas sin aprobación es vender otro producto.","correcta":true,"retro":"Correcto. El registro ampara lo que se evaluó, no cualquier versión del producto."},{"texto":"Porque cada modificación genera una tarifa, y el registro solo se mantiene vigente si se pagan al Invima las tarifas anuales.","correcta":false,"retro":"Las tarifas existen, pero la razón de fondo es que el registro ampara condiciones evaluadas."},{"texto":"Porque la ley obliga a actualizar el registro cada vez que cambia el representante legal de la empresa.","correcta":false,"retro":"Ese es un cambio administrativo; la pregunta trata de cambios que afectan el producto."},{"texto":"Porque cada modificación reinicia la vigencia del registro, que de otro modo vencería a los cinco años de expedido.","correcta":false,"retro":"Desde el Decreto 1474 de 2023 la vigencia del registro de medicamentos es indefinida; la modificación existe porque el registro ampara condiciones aprobadas."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 08. Farmacovigilancia y poscomercialización
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Farmacovigilancia y poscomercialización$t$
     AND m.title = $u$Después del registro$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Farmacovigilancia y poscomercialización$t$, $u$Después del registro$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Farmacovigilancia y poscomercialización","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de farmacovigilancia y poscomercialización. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar farmacovigilancia y poscomercialización con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar farmacovigilancia y poscomercialización con después del registro y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar farmacovigilancia y poscomercialización y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Obtener el registro activa obligaciones: reportar eventos adversos, mantener un sistema de farmacovigilancia y responder ante señales de seguridad. Esta clase conecta el trabajo regulatorio con el del paciente real."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, farmacovigilancia y poscomercialización aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de después del registro. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Obtener el registro activa obligaciones: reportar eventos adversos, mantener un sistema de farmacovigilancia y responder ante señales de seguridad. Esta clase conecta el trabajo regulatorio con el del paciente real.","Una pregunta que se usa para comprobar esta clase es: «El titular de un registro recibe el reporte de un paciente hospitalizado por una reacción adversa grave atribuida a su medicamento. ¿Qué debe hacer con ese caso?» La respuesta correcta se apoya en lo siguiente: Desde el 1 de marzo de 2025, la Resolución 2024015321 de 2024 del Invima obliga al titular a comunicar los eventos adversos serios dentro de los 15 días calendario siguientes al día en que los conoce, y los no serios dentro de los 90, por eReporting Industria. Se reporta la sospecha; la causalidad se evalúa después. La fuente citada es: Resolución 2024015321 de 2024 del Invima, artículo 8; ICH E2A, definición de evento serio.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a después del registro y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de cumplimiento poscomercialización con calendario, decisiones y prioridades.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar farmacovigilancia y poscomercialización, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y separa las cinco situaciones. Evidencia que debe quedar: Registro del paso.","Para el cambio de fabricante del principio activo, define el trámite, la documentación de soporte y si se puede vender con el nuevo fabricante antes de la aprobación. Evidencia que debe quedar: Registro del paso.","Explica al gerente comercial qué significa la vigencia indefinida del registro (Decreto 1474 de 2023) y qué condiciones la sostienen. Evidencia que debe quedar: Registro del paso.","Define qué se hace con los tres reportes: plazos, canal, evaluación de causalidad y análisis de señal. Evidencia que debe quedar: Registro del paso.","Responde a mercadeo sobre el comercial y los influenciadores con la norma aplicable y una alternativa permitida. Evidencia que debe quedar: Registro del paso.","Prepara la lista de verificación para la visita del Invima a la bodega. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar farmacovigilancia y poscomercialización en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Farmacovigilancia y poscomercialización»?","respuesta":"Obtener el registro activa obligaciones: reportar eventos adversos, mantener un sistema de farmacovigilancia y responder ante señales de seguridad. Esta clase conecta el trabajo regulatorio con el del paciente real."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de cumplimiento poscomercialización con calendario, decisiones y prioridades.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Farmacovigilancia y poscomercialización se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con después del registro.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA · Programa Nacional de Farmacovigilancia. Las obligaciones que empiezan cuando se obtiene el registro, no cuando se pide.","url":"https://www.invima.gov.co/farmacovigilancia"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente farmacovigilancia y poscomercialización en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de farmacovigilancia y poscomercialización"}],"keywords":["asuntos","regulatorios","sanitarios","invima","farmacovigilancia","poscomercialización","después","registro"],"mapa":{"centro":"Farmacovigilancia y poscomercialización","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Después del registro","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Plan de cumplimiento poscomercialización","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y separa las cinco situaciones.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para el cambio de fabricante del principio activo, define el trámite, la documentación de soporte y si se puede vender con el nuevo fabricante antes de la aprobación.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Explica al gerente comercial qué significa la vigencia indefinida del registro (Decreto 1474 de 2023) y qué condiciones la sostienen.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Define qué se hace con los tres reportes: plazos, canal, evaluación de causalidad y análisis de señal.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Responde a mercadeo sobre el comercial y los influenciadores con la norma aplicable y una alternativa permitida.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prepara la lista de verificación para la visita del Invima a la bodega.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Farmacovigilancia y poscomercialización","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de después del registro: Distribuciones Andes Pharma (ficticia) es titular del registro sanitario de unas tabletas de venta con fórmula médica. En la misma semana ocurre lo siguiente: compras propone cambiar el fabricante del principio activo por uno más barato; llegan tres reportes de eventos adversos, uno de ellos con hospitalización; mercadeo propone un comercial de televisión y una campaña con influenciadores; el gerente comercial afirma que «como el registro ya no vence, no hay que volver a tocarlo»; y el Invima anuncia una visita de inspección a la bodega del importador para el próximo mes (datos simulados). La gerente te pide un plan para no poner en riesgo el registro. La pregunta que decide esta clase es: El titular de un registro recibe el reporte de un paciente hospitalizado por una reacción adversa grave atribuida a su medicamento. ¿Qué debe hacer con ese caso?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Esperar al informe periódico del semestre, porque los reportes de un producto se consolidan antes de enviarlos al Invima.","correcta":false,"retro":"Los eventos serios no esperan al informe periódico: tienen un plazo corto propio."},{"texto":"Reportarlo al Invima como serio dentro de los 15 días calendario siguientes a conocerlo, por eReporting Industria.","correcta":true,"retro":"Correcto. Una hospitalización hace serio el evento y activa el reporte en ese plazo, que cuenta desde el día siguiente al conocimiento."},{"texto":"Reportarlo solo si el médico tratante confirma por escrito que el medicamento fue la causa del evento.","correcta":false,"retro":"Se reporta la sospecha; la causalidad se evalúa después y no es requisito para reportar."},{"texto":"Retirar de inmediato todos los lotes del mercado y reportar el caso cuando termine la investigación.","correcta":false,"retro":"Un solo caso no implica retiro automático; el reporte oportuno es la primera obligación."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
