  -- 09. Publicidad, visitas y sanciones
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Publicidad, visitas y sanciones$t$
     AND m.title = $u$Después del registro$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Publicidad, visitas y sanciones$t$, $u$Después del registro$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Publicidad, visitas y sanciones","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de publicidad, visitas y sanciones. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar publicidad, visitas y sanciones con tus propias palabras y reconocer por qué importa en asuntos Regulatorios Sanitarios ante INVIMA.","Relacionar publicidad, visitas y sanciones con después del registro y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar publicidad, visitas y sanciones y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Qué se puede decir de un producto y qué no, cómo se verifica en una visita y qué consecuencias tiene incumplir. Cierra el curso con el lado que más rápido se nota cuando falla."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, publicidad, visitas y sanciones aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de después del registro. El objetivo del curso es claro: Que puedas armar y sostener un expediente de registro sanitario sin perderte en el camino. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Qué se puede decir de un producto y qué no, cómo se verifica en una visita y qué consecuencias tiene incumplir. Cierra el curso con el lado que más rápido se nota cuando falla.","Una pregunta que se usa para comprobar esta clase es: «La marca de un antihipertensivo de venta con fórmula médica publica en redes sociales: «Controla tu presión con X; pregúntale a tu médico». ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: El artículo 11 del Decreto 334 de 2022 limita la información y la publicidad de los medicamentos de venta con fórmula a publicaciones de distribución restringida, dirigidas a profesionales en medicina y odontología, y las prohíbe en medios masivos, plataformas digitales, mensajería y redes sociales. La fuente citada es: Decreto 334 de 2022, artículo 11; Resolución 1896 de 2023 del Ministerio de Salud.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a después del registro y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de cumplimiento poscomercialización con calendario, decisiones y prioridades.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar publicidad, visitas y sanciones, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y separa las cinco situaciones. Evidencia que debe quedar: Registro del paso.","Para el cambio de fabricante del principio activo, define el trámite, la documentación de soporte y si se puede vender con el nuevo fabricante antes de la aprobación. Evidencia que debe quedar: Registro del paso.","Explica al gerente comercial qué significa la vigencia indefinida del registro (Decreto 1474 de 2023) y qué condiciones la sostienen. Evidencia que debe quedar: Registro del paso.","Define qué se hace con los tres reportes: plazos, canal, evaluación de causalidad y análisis de señal. Evidencia que debe quedar: Registro del paso.","Responde a mercadeo sobre el comercial y los influenciadores con la norma aplicable y una alternativa permitida. Evidencia que debe quedar: Registro del paso.","Prepara la lista de verificación para la visita del Invima a la bodega. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar publicidad, visitas y sanciones en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Publicidad, visitas y sanciones»?","respuesta":"Qué se puede decir de un producto y qué no, cómo se verifica en una visita y qué consecuencias tiene incumplir. Cierra el curso con el lado que más rápido se nota cuando falla."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de cumplimiento poscomercialización con calendario, decisiones y prioridades.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Publicidad, visitas y sanciones se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con después del registro.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Decreto 677 de 1995 · Publicidad y régimen sancionatorio. Qué se puede afirmar de un producto, cómo se verifica y qué consecuencias tiene incumplir.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente publicidad, visitas y sanciones en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de publicidad, visitas y sanciones"}],"keywords":["asuntos","regulatorios","sanitarios","invima","publicidad","visitas","sanciones","después","registro"],"mapa":{"centro":"Publicidad, visitas y sanciones","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios","Después del registro","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Plan de cumplimiento poscomercialización","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y separa las cinco situaciones.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Para el cambio de fabricante del principio activo, define el trámite, la documentación de soporte y si se puede vender con el nuevo fabricante antes de la aprobación.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Explica al gerente comercial qué significa la vigencia indefinida del registro (Decreto 1474 de 2023) y qué condiciones la sostienen.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Define qué se hace con los tres reportes: plazos, canal, evaluación de causalidad y análisis de señal.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Responde a mercadeo sobre el comercial y los influenciadores con la norma aplicable y una alternativa permitida.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Prepara la lista de verificación para la visita del Invima a la bodega.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Publicidad, visitas y sanciones","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de después del registro: Distribuciones Andes Pharma (ficticia) es titular del registro sanitario de unas tabletas de venta con fórmula médica. En la misma semana ocurre lo siguiente: compras propone cambiar el fabricante del principio activo por uno más barato; llegan tres reportes de eventos adversos, uno de ellos con hospitalización; mercadeo propone un comercial de televisión y una campaña con influenciadores; el gerente comercial afirma que «como el registro ya no vence, no hay que volver a tocarlo»; y el Invima anuncia una visita de inspección a la bodega del importador para el próximo mes (datos simulados). La gerente te pide un plan para no poner en riesgo el registro. La pregunta que decide esta clase es: La marca de un antihipertensivo de venta con fórmula médica publica en redes sociales: «Controla tu presión con X; pregúntale a tu médico». ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es válida porque remite al médico, y esa frase convierte cualquier pieza en información educativa.","correcta":false,"retro":"Remitir al médico no cambia que se esté promoviendo al público un medicamento de prescripción."},{"texto":"Es válida si la pieza muestra el número de registro sanitario y las contraindicaciones principales.","correcta":false,"retro":"Agregar datos no habilita la publicidad al público de un producto de venta con fórmula."},{"texto":"No es válida: los de venta con fórmula solo se anuncian en publicaciones restringidas a médicos y odontólogos.","correcta":true,"retro":"Correcto. El Decreto 334 de 2022 prohíbe expresamente anunciarlos en redes sociales, medios masivos y plataformas digitales."},{"texto":"No es válida solo porque las redes sociales no están reguladas todavía como medio publicitario de medicamentos en Colombia.","correcta":false,"retro":"Las redes sí están reguladas: el Decreto 334 de 2022 las prohíbe para los medicamentos de venta con fórmula."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases completas con experiencia interactiva (catálogo).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;
  RAISE NOTICE 'Experiencias de %: % clases.', $t$Asuntos Regulatorios Sanitarios ante INVIMA$t$, v_n;
END $curso$;
